def intermediate_pronunciation_grade_from_payload(payload):
    try:
        score100 = float(payload.get("score100"))
    except (TypeError, ValueError):
        raise ValueError("invalid_score")
    if score100 < 0 or score100 > 100:
        raise ValueError("invalid_score")
    grade = round((score100 / 20.0) * 100) / 100
    return int(round(score100)), grade


def basic2_unit1_pronunciation_report_from_payload(payload):
    raw_scores = payload.get("stageScores")
    if not isinstance(raw_scores, list) or len(raw_scores) != 7:
        raise ValueError("incomplete_pronunciation_report")
    stage_scores = []
    total_score = 0.0
    for index, item in enumerate(raw_scores):
        if not isinstance(item, dict):
            raise ValueError("invalid_pronunciation_stage")
        overall = clean_score_metric(item.get("overall"))
        if overall is None:
            raise ValueError("invalid_pronunciation_score")
        accuracy = clean_score_metric(item.get("accuracy"))
        completeness = clean_score_metric(item.get("completeness"))
        fluency = clean_score_metric(item.get("fluency"))
        wpm = clean_score_metric(item.get("wpm"), 0, 300)
        total_score += overall
        stage_scores.append({
            "stage": clean_text(item.get("stage") or item.get("stageLabel"), 120) or ("Section " + str(index + 1)),
            "overall": overall,
            "accuracy": accuracy,
            "completeness": completeness,
            "fluency": fluency,
            "wpm": wpm,
            "transcript": clean_text(item.get("transcript"), 3000),
            "referenceText": clean_text(item.get("referenceText"), 3000),
            "missedWords": clean_text_list(item.get("missedWords"), 40, 80),
            "final": bool(item.get("final")) or index == 6,
            "at": clean_text(item.get("at"), 80)
        })
    score100 = int(round(total_score / len(stage_scores)))
    grade = round((score100 / 20.0) * 100) / 100
    final_stage = stage_scores[-1]
    return {
        "score100": score100,
        "grade": grade,
        "stageScores": stage_scores,
        "finalTranscript": final_stage.get("transcript", ""),
        "finalReferenceText": final_stage.get("referenceText", ""),
        "finalMissedWords": final_stage.get("missedWords", []),
        "clientSubmissionId": clean_text(payload.get("clientSubmissionId"), 120)
    }


def score_intermediate_fixed_answers(payload, answer_key):
    raw_answers = payload.get("answers")
    if not isinstance(raw_answers, list):
        raise ValueError("invalid_answers")
    if len(raw_answers) != len(answer_key):
        raise ValueError("incomplete_answers")
    answers = []
    score = 0
    incorrect = []
    max_answer = max([2] + [int(answer) for answer in answer_key])
    for index, correct in enumerate(answer_key):
        try:
            answer = int(raw_answers[index])
        except (TypeError, ValueError):
            raise ValueError("invalid_answers")
        if answer < 0 or answer > max_answer:
            raise ValueError("invalid_answers")
        answers.append(answer)
        if answer == correct:
            score += 1
        else:
            incorrect.append(index + 1)
    total = len(answer_key)
    grade = round((score / total) * 5, 2)
    return {
        "answers": answers,
        "score": score,
        "total": total,
        "grade": grade,
        "incorrect": incorrect
    }


def clean_intermediate_text_followup(payload, text_key, min_words, max_words):
    text = clean_text(payload.get(text_key), 5000)
    word_count = simple_word_count(text)
    if word_count < min_words:
        raise ValueError("text_too_short")
    if word_count > max_words:
        raise ValueError("text_too_long")
    return text, word_count


def save_intermediate_text_followup(student, evaluation_id, detail):
    previous = student.get("gradeDetails", {}).get(evaluation_id) if isinstance(student.get("gradeDetails"), dict) else None
    try:
        attempt_count = int(previous.get("attemptCount", 0)) + 1 if isinstance(previous, dict) else 1
    except (TypeError, ValueError):
        attempt_count = 1
    submitted_at = now_iso()
    if not isinstance(student.get("gradeDetails"), dict):
        student["gradeDetails"] = {}
    next_detail = dict(detail)
    next_detail.update({
        "submittedAt": submitted_at,
        "attemptCount": attempt_count,
        "status": "submitted",
        "weight": 0,
        "doesNotAffectAverage": True,
        "followUpOnly": True
    })
    student["gradeDetails"][evaluation_id] = next_detail
    return submitted_at, attempt_count


def strict_finite_number(value, minimum, maximum, error_code):
    if isinstance(value, bool):
        raise ValueError(error_code)
    try:
        number = float(value)
    except (TypeError, ValueError):
        raise ValueError(error_code)
    if not math.isfinite(number) or number < minimum or number > maximum:
        raise ValueError(error_code)
    return round(number, 2)


def clean_intermediate_unit5_restaurant_coach(payload):
    metric_keys = ("task", "interaction", "language", "fluency", "clarity")
    raw_metrics = payload.get("metrics")
    if not isinstance(raw_metrics, dict):
        raise ValueError("invalid_metrics")
    metrics = {
        key: strict_finite_number(raw_metrics.get(key), 0, 10, "invalid_metrics")
        for key in metric_keys
    }
    score = round(sum(metrics.values()), 2)
    grade = round(score / 10.0, 2)

    try:
        analyzed_count = int(payload.get("analyzedCount"))
        total_stages = int(payload.get("totalStages"))
    except (TypeError, ValueError):
        raise ValueError("incomplete_conversation")
    if analyzed_count != 6 or total_stages != 6:
        raise ValueError("incomplete_conversation")

    raw_stage_scores = payload.get("stageScores")
    if not isinstance(raw_stage_scores, list) or len(raw_stage_scores) != 6:
        raise ValueError("incomplete_conversation")
    stage_scores = [
        strict_finite_number(value, 0, 50, "invalid_stage_scores")
        for value in raw_stage_scores
    ]

    raw_turns = payload.get("turns")
    if not isinstance(raw_turns, list) or len(raw_turns) < 6 or len(raw_turns) > 12:
        raise ValueError("incomplete_conversation")
    stage_topics = (
        "Arrival and table",
        "Preferences and dietary needs",
        "Ask about the menu",
        "Place the order",
        "Resolve a service problem",
        "Request the check",
    )
    turns = []
    scored_stages = set()
    for raw_turn in raw_turns:
        if not isinstance(raw_turn, dict):
            raise ValueError("invalid_turns")
        try:
            stage_index = int(raw_turn.get("stageIndex"))
        except (TypeError, ValueError):
            raise ValueError("invalid_turns")
        if stage_index < 0 or stage_index >= 6:
            raise ValueError("invalid_turns")
        phase = "clarify" if raw_turn.get("phase") == "clarify" else "main"
        prompt = clean_text(raw_turn.get("prompt"), 900)
        transcript = clean_text(raw_turn.get("transcript"), 1800)
        if len(prompt) < 3 or len(transcript) < 3:
            raise ValueError("invalid_turns")
        turn_score = None
        if raw_turn.get("score") is not None:
            turn_score = strict_finite_number(raw_turn.get("score"), 0, 50, "invalid_turns")
            scored_stages.add(stage_index)
        turns.append({
            "stageIndex": stage_index,
            "topic": stage_topics[stage_index],
            "phase": phase,
            "prompt": prompt,
            "transcript": transcript,
            "score": turn_score,
        })
    if scored_stages != set(range(6)):
        raise ValueError("incomplete_conversation")

    mode = clean_text(payload.get("mode"), 20)
    if mode not in ("guided", "real"):
        raise ValueError("invalid_mode")
    selected_dish = clean_text(payload.get("selectedDish"), 160)
    service_scenario = clean_text(payload.get("serviceScenario"), 420)
    transcript_lines = [
        "Mode: " + ("Real Restaurant" if mode == "real" else "Guided Rehearsal"),
        "Selected dish: " + (selected_dish or "Not specified"),
        "Service scenario: " + (service_scenario or "Not specified"),
        "",
    ]
    for turn in turns:
        phase_label = "Clarification" if turn["phase"] == "clarify" else "Initial response"
        score_label = "Not analyzed" if turn["score"] is None else f'{turn["score"]:g}/50'
        transcript_lines.extend([
            f'Stage {turn["stageIndex"] + 1} - {turn["topic"]} ({phase_label})',
            "Ethan: " + turn["prompt"],
            "Student: " + turn["transcript"],
            "Reference stage score: " + score_label,
            "",
        ])

    return {
        "score": score,
        "total": 50,
        "grade": grade,
        "metrics": metrics,
        "analyzedCount": analyzed_count,
        "totalStages": total_stages,
        "stageScores": stage_scores,
        "turns": turns,
        "mode": mode,
        "selectedDish": selected_dish,
        "serviceScenario": service_scenario,
        "transcript": "\n".join(transcript_lines).strip(),
    }


def clean_intermediate_partial_coach_report(payload, stage_topics):
    metric_keys = ("task", "interaction", "language", "fluency", "clarity")
    raw_metrics = payload.get("metrics")
    if not isinstance(raw_metrics, dict):
        raise ValueError("invalid_metrics")
    metrics = {
        key: strict_finite_number(raw_metrics.get(key), 0, 10, "invalid_metrics")
        for key in metric_keys
    }
    stage_count = len(stage_topics)

    try:
        analyzed_count = int(payload.get("analyzedCount") or 0)
    except (TypeError, ValueError):
        analyzed_count = 0
    analyzed_count = max(0, min(stage_count, analyzed_count))
    total_stages = stage_count

    raw_stage_scores = payload.get("stageScores")
    if not isinstance(raw_stage_scores, list):
        raw_stage_scores = []
    stage_scores = []
    for index in range(stage_count):
        value = raw_stage_scores[index] if index < len(raw_stage_scores) else None
        if value in (None, ""):
            stage_scores.append(None)
            continue
        stage_scores.append(strict_finite_number(value, 0, 50, "invalid_stage_scores"))

    raw_turns = payload.get("turns")
    if not isinstance(raw_turns, list):
        raw_turns = []
    raw_turns = raw_turns[:stage_count * 2]
    turns = []
    scored_stages = set()
    for raw_turn in raw_turns:
        if not isinstance(raw_turn, dict):
            continue
        try:
            stage_index = int(raw_turn.get("stageIndex"))
        except (TypeError, ValueError):
            continue
        if stage_index < 0 or stage_index >= stage_count:
            continue
        phase = "clarify" if raw_turn.get("phase") == "clarify" else "main"
        prompt = clean_text(raw_turn.get("prompt"), 900) or stage_topics[stage_index]
        transcript = clean_text(raw_turn.get("transcript"), 1800) or "No response recorded before continuing."
        turn_score = None
        if raw_turn.get("score") is not None:
            turn_score = strict_finite_number(raw_turn.get("score"), 0, 50, "invalid_turns")
            scored_stages.add(stage_index)
            if stage_scores[stage_index] is None:
                stage_scores[stage_index] = turn_score
        turns.append({
            "stageIndex": stage_index,
            "topic": stage_topics[stage_index],
            "phase": phase,
            "prompt": prompt,
            "transcript": transcript,
            "score": turn_score,
        })
    present_stages = {turn["stageIndex"] for turn in turns}
    for stage_index in range(stage_count):
        if stage_index in present_stages:
            continue
        turns.append({
            "stageIndex": stage_index,
            "topic": stage_topics[stage_index],
            "phase": "main",
            "prompt": stage_topics[stage_index],
            "transcript": "No response recorded before continuing.",
            "score": None,
        })
    turns.sort(key=lambda turn: (turn["stageIndex"], 1 if turn["phase"] == "clarify" else 0))

    complete_conversation = (
        analyzed_count == stage_count
        and scored_stages == set(range(stage_count))
        and all(isinstance(value, (int, float)) and math.isfinite(value) for value in stage_scores)
    )
    if complete_conversation:
        score = round(sum(metrics.values()), 2)
    else:
        scored_values = [
            stage_scores[index]
            for index in range(stage_count)
            if index in scored_stages and isinstance(stage_scores[index], (int, float)) and math.isfinite(stage_scores[index])
        ]
        score = round(sum(scored_values) / stage_count, 2) if scored_values else 0
    grade = round(score / 10.0, 2)
    return {
        "score": score,
        "total": 50,
        "grade": grade,
        "metrics": metrics,
        "analyzedCount": analyzed_count,
        "totalStages": total_stages,
        "stageScores": stage_scores,
        "turns": turns,
        "partialSubmission": not complete_conversation,
        "completeConversation": complete_conversation,
    }


