def final_exam_parse_utc(value):
    """Parse a public exam timestamp as an aware UTC datetime."""

    if isinstance(value, datetime):
        parsed = value
    elif isinstance(value, (int, float)) and not isinstance(value, bool):
        try:
            parsed = datetime.fromtimestamp(float(value), timezone.utc)
        except (OverflowError, OSError, ValueError):
            return None
    else:
        text = clean_text(value, 80)
        if not text:
            return None
        try:
            parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
        except (TypeError, ValueError):
            return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def final_exam_iso_utc(value):
    parsed = final_exam_parse_utc(value)
    return parsed.isoformat().replace("+00:00", "Z") if parsed else None


def final_exam_schedule_status(state, now=None):
    """Return the server-authoritative status of an optional exam window."""

    if not isinstance(state, dict) or state.get("scheduleEnabled") is not True:
        return "manual_open" if isinstance(state, dict) and state.get("isOpen") is True else "manual_closed"
    opens_at = final_exam_parse_utc(state.get("opensAt"))
    closes_at = final_exam_parse_utc(state.get("closesAt"))
    current = final_exam_parse_utc(now) if now is not None else datetime.now(timezone.utc)
    if not opens_at or not closes_at or closes_at <= opens_at or not current:
        return "invalid"
    if current < opens_at:
        return "scheduled"
    if current >= closes_at:
        return "closed"
    return "open"


def final_exam_refresh_schedule_state(state, now=None, allow_open=True):
    """Materialize a scheduled window without trusting client clocks.

    ``allow_open=False`` is the fail-closed read path used by Niveau 8.  It may
    materialize a due close, but it cannot turn a stored closed state into an
    open one.  Only the autonomous scheduler (after its opening health gate) or
    an already validated staff action may do that.
    """

    if not isinstance(state, dict) or state.get("scheduleEnabled") is not True:
        return False
    status = final_exam_schedule_status(state, now)
    previous = (
        state.get("isOpen") is True,
        state.get("openedAt"),
        state.get("closedAt"),
        state.get("scheduleStatus"),
    )
    state["scheduleStatus"] = status
    if status == "open" and (allow_open or state.get("isOpen") is True):
        state["isOpen"] = True
        state["openedAt"] = final_exam_iso_utc(state.get("opensAt"))
        state["closedAt"] = None
    elif status == "open":
        state["isOpen"] = False
        state["openedAt"] = None
        state["closedAt"] = None
    elif status == "closed":
        state["isOpen"] = False
        state["closedAt"] = final_exam_iso_utc(state.get("closesAt"))
    else:
        state["isOpen"] = False
        if status == "scheduled":
            state["openedAt"] = None
            state["closedAt"] = None
    current = (
        state.get("isOpen") is True,
        state.get("openedAt"),
        state.get("closedAt"),
        state.get("scheduleStatus"),
    )
    return current != previous


