def final_exam_audio_path(config):
    configured = config.get("audioPath")
    if configured and os.path.exists(configured):
        return configured
    return config.get("bundledAudioPath")


def final_exam_question_count(exam):
    return sum(
        1
        for section in exam.get("sections", [])
        if isinstance(section, dict)
        for question in section.get("questions", [])
        if isinstance(question, dict) and clean_text(question.get("id"), 80)
    )


def final_exam_integrity(exam, audio_path):
    issues = []
    seen = set()
    computed_points = 0.0
    for section in exam.get("sections", []):
        if not isinstance(section, dict):
            continue
        for question in section.get("questions", []):
            if not isinstance(question, dict):
                continue
            question_id = clean_text(question.get("id"), 80)
            if not question_id:
                issues.append("question_without_id")
            elif question_id in seen:
                issues.append("duplicate_question:" + question_id)
            seen.add(question_id)
            try:
                computed_points += float(question.get("points", 1))
            except (TypeError, ValueError):
                issues.append("invalid_points:" + (question_id or "unknown"))
            question_type = clean_text(question.get("type"), 40).lower()
            answer = question.get("answer")
            if question_type == "truefalse":
                if not isinstance(answer, bool):
                    issues.append("invalid_answer:" + (question_id or "unknown"))
            else:
                options = question.get("options")
                if not isinstance(options, list) or not options:
                    issues.append("missing_options:" + (question_id or "unknown"))
                elif isinstance(answer, bool) or not isinstance(answer, int) or not 0 <= answer < len(options):
                    issues.append("invalid_answer:" + (question_id or "unknown"))
    try:
        configured_points = float(exam.get("totalPoints", 0))
    except (TypeError, ValueError):
        configured_points = 0.0
    if abs(computed_points - configured_points) > 0.001:
        issues.append("points_mismatch")
    if not clean_text(exam.get("version"), 80):
        issues.append("missing_version")
    if not clean_text(exam.get("transcript"), 5000):
        issues.append("missing_transcript")
    if not audio_path or not os.path.exists(audio_path) or os.path.getsize(audio_path) < 10000:
        issues.append("audio_not_ready")
    return {
        "ok": not issues and bool(seen),
        "issues": issues[:20],
        "questions": len(seen),
        "configuredPoints": clean_exam_number(configured_points),
        "computedPoints": clean_exam_number(computed_points),
        "audioAvailable": bool(audio_path and os.path.exists(audio_path)),
    }


def final_exam_append_event(store, event_type, profile=None, student=None, extra=None):
    events = store.setdefault("events", [])
    if not isinstance(events, list):
        events = []
        store["events"] = events
    event = {
        "eventId": secrets.token_urlsafe(12),
        "at": now_iso(),
        "event": clean_text(event_type, 80),
        "email": normalize_email(profile.get("email")) if isinstance(profile, dict) else "",
        "studentId": clean_text(student.get("id"), 40) if isinstance(student, dict) else "",
        "requestId": (
            clean_text((extra or {}).get("requestId"), 120)
            if isinstance(extra, dict) and (extra or {}).get("requestId")
            else clean_text((profile or {}).get("_requestId"), 120)
        ),
    }
    if isinstance(extra, dict):
        for key, value in extra.items():
            event[clean_text(key, 60)] = clean_text(value, 300) if isinstance(value, str) else value
    events.append(event)
    del events[:-1000]


def final_exam_public_state(state, role, student_id=""):
    schedule_status = final_exam_schedule_status(state)
    schedule_enabled = state.get("scheduleEnabled") is True
    effective_open = (
        schedule_status == "open" and state.get("isOpen") is True
        if schedule_enabled
        else state.get("isOpen") is True
    )
    opening_gate = state.get("openingGate") if isinstance(state.get("openingGate"), dict) else {}
    opening_gate_blocked = (
        schedule_enabled
        and schedule_status == "open"
        and not effective_open
        and opening_gate.get("status") == "blocked"
    )
    result = {
        "isOpen": effective_open,
        "openedAt": state.get("openedAt"),
        "closedAt": state.get("closedAt"),
        "updatedAt": state.get("updatedAt"),
        "durationMinutes": state.get("durationMinutes", 90),
        "releaseResults": state.get("releaseResults") is True,
        "releasedAt": state.get("releasedAt"),
        "revision": state.get("revision", 0),
        "serverTime": now_iso(),
    }
    if schedule_enabled or "opensAt" in state or "closesAt" in state:
        if schedule_status == "open" and effective_open:
            access_reason = "scheduled_window_open"
        elif schedule_status == "open" and opening_gate_blocked:
            access_reason = "scheduled_open_health_blocked"
        elif schedule_status == "open":
            access_reason = "scheduled_open_pending_scheduler"
        else:
            access_reason = {
                "scheduled": "before_scheduled_open",
                "closed": "scheduled_window_closed",
                "invalid": "invalid_schedule",
                "manual_open": "opened_by_teacher",
                "manual_closed": "closed_by_teacher",
            }.get(schedule_status, "closed_by_teacher")
        result.update({
            "scheduleEnabled": schedule_enabled,
            "opensAt": final_exam_iso_utc(state.get("opensAt")),
            "closesAt": final_exam_iso_utc(state.get("closesAt")),
            "scheduleStatus": schedule_status,
            "accessEffective": effective_open,
            "accessReason": access_reason,
            "openingGateStatus": clean_text(opening_gate.get("status"), 40) or "idle",
        })
    extras = state.get("extraMinutesByStudent", {})
    if not isinstance(extras, dict):
        extras = {}
    if role in ("admin", "teacher"):
        result["openedBy"] = state.get("openedBy")
        result["extraMinutesByStudent"] = extras
        if opening_gate:
            result["openingGate"] = {
                "status": clean_text(opening_gate.get("status"), 40) or "unknown",
                "checkedAt": opening_gate.get("checkedAt"),
                "blockedAt": opening_gate.get("blockedAt"),
                "recoveredAt": opening_gate.get("recoveredAt"),
                "healthStatus": clean_text(opening_gate.get("healthStatus"), 40),
                "blockingIssues": [
                    clean_text(item, 80)
                    for item in opening_gate.get("blockingIssues", [])
                    if clean_text(item, 80)
                ],
                "lastError": clean_text(opening_gate.get("lastError"), 300),
            }
    else:
        try:
            result["extraMinutes"] = int(extras.get(student_id, 0) or 0)
        except (TypeError, ValueError):
            result["extraMinutes"] = 0
    return result


def french8_final_exam_audio_is_public(bundle):
    """Allow the listening file without a credential only during the effective exam window."""

    state = bundle.get("state", {}) if isinstance(bundle, dict) else {}
    public_state = final_exam_public_state(state, "student", "")
    return public_state.get("accessEffective", public_state.get("isOpen")) is True


def french8_final_exam_audio_grant(profile, role, student, bundle):
    """Create a short-lived grant so native audio can use HTTP Range requests."""

    state = bundle.get("state", {}) if isinstance(bundle, dict) else {}
    exam = bundle.get("exam", {}) if isinstance(bundle, dict) else {}
    student_id = clean_text(student.get("id"), 40) if isinstance(student, dict) else ""
    is_staff = role in ("admin", "teacher")
    public_state = final_exam_public_state(state, role, student_id)
    if not is_staff and public_state.get("isOpen") is not True:
        return 403, {"error": "exam_closed", "state": public_state}
    now_epoch = int(time.time())
    ttl = max(300, min(int(FRENCH8_FINAL_EXAM_AUDIO_GRANT_TTL or 10800), 21600))
    expires_at = now_epoch + ttl
    scheduled_close = final_exam_parse_utc(state.get("closesAt")) if state.get("scheduleEnabled") is True else None
    if scheduled_close and not is_staff:
        expires_at = min(expires_at, int(scheduled_close.timestamp()) + 60)
    claims = {
        "purpose": "french8-final-exam-audio",
        "email": normalize_email((profile or {}).get("email")),
        "studentId": student_id,
        "staff": is_staff,
        "examVersion": clean_text(exam.get("version"), 80),
        "stateRevision": int(state.get("revision", 0) or 0),
        "iat": now_epoch,
        "exp": expires_at,
        "nonce": secrets.token_urlsafe(10),
    }
    encoded = base64.urlsafe_b64encode(
        json.dumps(claims, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).decode("ascii").rstrip("=")
    signature = hmac.new(
        local_auth_secret(),
        ("french8-final-exam-audio|" + encoded).encode("utf-8"),
        hashlib.sha256,
    ).hexdigest()
    grant = encoded + "." + signature
    return 200, {
        "ok": True,
        "audioUrl": "/api/french8/final-exam/audio?" + urllib.parse.urlencode({"grant": grant}),
        "expiresAt": datetime.fromtimestamp(expires_at, timezone.utc).isoformat().replace("+00:00", "Z"),
        "contentType": "audio/mpeg",
        "acceptRanges": "bytes",
    }


def french8_final_exam_validate_audio_grant(grant, bundle, now=None):
    """Validate an opaque native-audio grant without exposing identity data."""

    token = clean_text(grant, 4096)
    if not token or "." not in token:
        raise ValueError("audio_grant_missing")
    encoded, supplied_signature = token.rsplit(".", 1)
    expected_signature = hmac.new(
        local_auth_secret(),
        ("french8-final-exam-audio|" + encoded).encode("utf-8"),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(supplied_signature, expected_signature):
        raise ValueError("audio_grant_invalid")
    try:
        padding = "=" * ((4 - len(encoded) % 4) % 4)
        claims = json.loads(base64.urlsafe_b64decode((encoded + padding).encode("ascii")).decode("utf-8"))
    except (ValueError, UnicodeDecodeError, json.JSONDecodeError, binascii.Error) as error:
        raise ValueError("audio_grant_invalid") from error
    if not isinstance(claims, dict) or claims.get("purpose") != "french8-final-exam-audio":
        raise ValueError("audio_grant_invalid")
    current_epoch = int(time.time() if now is None else now)
    try:
        expires_at = int(claims.get("exp", 0))
    except (TypeError, ValueError):
        expires_at = 0
    if expires_at <= current_epoch:
        raise ValueError("audio_grant_expired")
    exam = bundle.get("exam", {}) if isinstance(bundle, dict) else {}
    state = bundle.get("state", {}) if isinstance(bundle, dict) else {}
    if clean_text(claims.get("examVersion"), 80) != clean_text(exam.get("version"), 80):
        raise ValueError("audio_grant_stale")
    try:
        grant_revision = int(claims.get("stateRevision", -1))
    except (TypeError, ValueError):
        grant_revision = -1
    if grant_revision != int(state.get("revision", 0) or 0):
        raise ValueError("audio_grant_stale")
    if claims.get("staff") is not True and final_exam_public_state(state, "student", clean_text(claims.get("studentId"), 40)).get("isOpen") is not True:
        raise ValueError("exam_closed")
    return claims


def final_exam_runtime_state_payload(profile, grades_data, bundle, store):
    """Build N1/N2 state without treating a staff roster match as a submission."""

    role, student = final_exam_authorized(profile, grades_data)
    student_id = clean_text(student.get("id"), 40) if isinstance(student, dict) else ""
    payload = final_exam_state_payload(profile, grades_data, bundle, store, strict_student=True)
    payload["state"] = final_exam_public_state(bundle.get("state", {}), role, student_id)
    payload["submitted"] = french1_final_exam_submission_public(
        payload.get("submitted"),
        bundle.get("state", {}),
        role in ("admin", "teacher"),
    )
    if role in ("admin", "teacher"):
        payload["submitted"] = None
    return payload


def final_exam_matching_attempt(store, student, exam):
    if not isinstance(student, dict) or not isinstance(store, dict):
        return None
    student_id = clean_text(student.get("id"), 40)
    attempt = store.get("attempts", {}).get(student_id) if student_id else None
    if not isinstance(attempt, dict):
        return None
    if clean_text(attempt.get("examVersion"), 80) != clean_text(exam.get("version"), 80):
        return None
    if clean_text(attempt.get("status"), 40) != "in_progress":
        return None
    return attempt


def final_exam_access_credentials(profile, config, attempt, exam):
    """Issue a short-lived local bridge for one active exam attempt."""

    if not isinstance(profile, dict) or not isinstance(config, dict) or not isinstance(attempt, dict):
        return {}
    level = clean_text(config.get("level"), 40)
    attempt_id = clean_text(attempt.get("attemptId"), 120)
    exam_version = clean_text(exam.get("version"), 80)
    if (
        not level
        or not attempt_id
        or clean_text(attempt.get("status"), 40) != "in_progress"
        or clean_text(attempt.get("examVersion"), 80) != exam_version
    ):
        return {}
    email = normalize_email(profile.get("email"))
    if not email:
        return {}
    name = clean_text(profile.get("name"), 200) or email
    signed_profile = {
        "provider": "local-gradebook",
        "sub": "local-gradebook:final-exam:" + level + ":" + email,
        "email": email,
        "name": name,
        "tokenPurpose": "final-exam",
        "examLevel": level,
        "examAttemptId": attempt_id,
        "examVersion": exam_version,
    }
    token, expires_at = sign_local_profile(signed_profile)
    return {
        "examAccessToken": token,
        "examAccessExp": expires_at,
        "examAccessUser": {
            "provider": "local",
            "authProvider": "local-gradebook",
            "email": email,
            "name": name,
            "level": level,
        },
    }


def is_final_exam_bridge_profile(profile):
    return isinstance(profile, dict) and clean_text(profile.get("tokenPurpose"), 80) == "final-exam"


def final_exam_bridge_route_allowed(profile, request_path, request_method="GET"):
    """Confine exam bridges to the exact student runtime routes they need."""

    if not is_final_exam_bridge_profile(profile):
        return True
    path = urllib.parse.urlparse(str(request_path or "")).path
    level = clean_text(profile.get("examLevel"), 40)
    if level not in ("french1", "french2", "french8"):
        return False
    base = "/api/" + level + "/final-exam"
    allowed = {
        "GET": {
            base,
            base + "/state",
            base + "/audio",
            base + "/audio-grant",
            base + "/draft",
            base + "/events",
        },
        "POST": {base + "/session", base + "/submit"},
        "PUT": {base + "/draft"},
    }
    return path in allowed.get(str(request_method or "").upper(), set())


def final_exam_bridge_attempt_error(profile, config, student, bundle, store, allow_submission=True):
    """Require bridge claims to match this student's active attempt or receipt."""

    if not is_final_exam_bridge_profile(profile):
        return None
    level = clean_text(config.get("level"), 40) if isinstance(config, dict) else ""
    claimed_level = clean_text(profile.get("examLevel"), 40)
    claimed_attempt = clean_text(profile.get("examAttemptId"), 120)
    claimed_version = clean_text(profile.get("examVersion"), 80)
    student_id = clean_text(student.get("id"), 40) if isinstance(student, dict) else ""
    if not level or claimed_level != level or not claimed_attempt or not claimed_version or not student_id:
        return 403, {"error": "token_scope_invalid"}

    submission = store.get("submissions", {}).get(student_id) if isinstance(store, dict) else None
    if allow_submission and isinstance(submission, dict):
        if (
            clean_text(submission.get("attemptId"), 120) == claimed_attempt
            and clean_text(submission.get("examVersion"), 80) == claimed_version
        ):
            return None

    attempt = store.get("attempts", {}).get(student_id) if isinstance(store, dict) else None
    current_version = clean_text(bundle.get("exam", {}).get("version"), 80) if isinstance(bundle, dict) else ""
    if (
        isinstance(attempt, dict)
        and clean_text(attempt.get("status"), 40) == "in_progress"
        and clean_text(attempt.get("attemptId"), 120) == claimed_attempt
        and clean_text(attempt.get("examVersion"), 80) == claimed_version
        and claimed_version == current_version
    ):
        return None
    return 403, {"error": "token_scope_invalid"}


def final_exam_access_payload(role, student, bundle, store, profile=None, config=None):
    """Expose questions only to staff or a student with a current attempt."""

    state = bundle.get("state", {})
    exam = bundle.get("exam", {})
    student_id = clean_text(student.get("id"), 40) if isinstance(student, dict) else ""
    payload = {
        "status": "staff-preview" if role in ("admin", "teacher") else "ready",
        "role": role,
        "state": final_exam_public_state(state, role, student_id),
        "student": student_public_view(student) if isinstance(student, dict) else None,
    }
    attempt = final_exam_matching_attempt(store, student, exam)
    if role in ("admin", "teacher"):
        payload["exam"] = final_exam_public_payload(bundle)
        return payload
    if isinstance(attempt, dict):
        session_payload = final_exam_attempt_public(attempt, state, student_id)
        payload.update({
            "status": "open",
            "exam": final_exam_public_payload(bundle),
            "session": session_payload,
            "attemptId": session_payload.get("attemptId"),
            "attemptSeed": session_payload.get("attemptSeed"),
            "timing": session_payload.get("timing"),
        })
        payload.update(final_exam_access_credentials(profile, config, attempt, exam))
        return payload
    payload.update({
        "examVersion": clean_text(exam.get("version"), 80),
        "examTitle": clean_text(exam.get("title") or "Examen final", 200),
        "totalPoints": exam.get("totalPoints", 50),
    })
    return payload


def final_exam_get_access_payload(role, student, bundle, store, profile=None, config=None):
    """Return a receipt instead of exam content once a student is submitted."""

    state = bundle.get("state", {})
    student_id = clean_text(student.get("id"), 40) if isinstance(student, dict) else ""
    submission = store.get("submissions", {}).get(student_id) if student_id else None
    if role not in ("admin", "teacher") and isinstance(submission, dict):
        return {
            "status": "submitted",
            "role": role,
            "state": final_exam_public_state(state, role, student_id),
            "student": student_public_view(student),
            "result": french1_final_exam_submission_public(submission, state),
        }
    return final_exam_access_payload(role, student, bundle, store, profile, config)


def final_exam_audio_access_error(role, student, bundle, store, require_active_attempt=True):
    """Describe why protected exam audio is unavailable to this student."""

    if role in ("admin", "teacher"):
        return None
    state = bundle.get("state", {})
    exam = bundle.get("exam", {})
    student_id = clean_text(student.get("id"), 40) if isinstance(student, dict) else ""
    if require_active_attempt is False:
        public_state = final_exam_public_state(state, role, student_id)
        if public_state.get("accessEffective", public_state.get("isOpen")) is not True:
            return 403, {"error": "exam_closed", "state": public_state}
        return None
    submission = store.get("submissions", {}).get(student_id) if student_id else None
    if isinstance(submission, dict):
        error = "attempt_expired" if submission.get("completionReason") == "time_expired" else "already_submitted"
        return 409, {
            "error": error,
            "result": french1_final_exam_submission_public(submission, state),
        }
    if state.get("isOpen") is not True:
        return 403, {
            "error": "exam_closed",
            "state": final_exam_public_state(state, role, student_id),
        }
    attempt = final_exam_matching_attempt(store, student, exam)
    if not isinstance(attempt, dict):
        return 409, {"error": "attempt_not_started"}
    if final_exam_attempt_timing(state, attempt, student_id).get("expired") is True:
        return 409, {"error": "attempt_expired"}
    return None


def final_exam_attempt_timing(state, attempt, student_id):
    started_at = attempt.get("startedAt") or state.get("openedAt") or now_iso()
    timing = exam_timing(
        started_at,
        state.get("durationMinutes", 90),
        student_id,
        state.get("extraMinutesByStudent", {}),
        now=time.time(),
    )
    if state.get("scheduleEnabled") is True:
        scheduled_close = final_exam_parse_utc(state.get("closesAt"))
        attempt_deadline = final_exam_parse_utc(timing.get("deadlineAt"))
        if scheduled_close and attempt_deadline and scheduled_close < attempt_deadline:
            current = datetime.now(timezone.utc)
            timing["deadlineAt"] = final_exam_iso_utc(scheduled_close)
            timing["remainingSeconds"] = max(
                0,
                int(math.ceil(scheduled_close.timestamp() - current.timestamp())),
            )
            timing["expired"] = current >= scheduled_close
            timing["scheduleLimited"] = True
    return timing


def final_exam_presentation(exam, seed):
    rng = random.Random(int(seed))
    sections = []
    question_orders = {}
    option_orders_all = {}
    for section in exam.get("sections", []):
        if not isinstance(section, dict):
            continue
        questions = [item for item in section.get("questions", []) if isinstance(item, dict)]
        question_ids = [clean_text(item.get("id"), 80) for item in questions if clean_text(item.get("id"), 80)]
        rng.shuffle(question_ids)
        option_orders = {}
        for question in questions:
            question_id = clean_text(question.get("id"), 80)
            options = question.get("options")
            if question_id and isinstance(options, list):
                order = list(range(len(options)))
                rng.shuffle(order)
                option_orders[question_id] = order
        sections.append({
            "sectionId": clean_text(section.get("id"), 80),
            "questionIds": question_ids,
            "optionOrders": option_orders,
        })
        section_id = clean_text(section.get("id"), 80)
        question_orders[section_id] = question_ids
        option_orders_all.update(option_orders)
    return {
        "sections": sections,
        "questions": question_orders,
        "questionOrder": question_orders,
        "options": option_orders_all,
    }


def french8_final_exam_simulation_payload(profile, role, bundle, variant="A"):
    """Build an explicit staff-only simulation without creating persisted state."""

    if role not in ("admin", "teacher"):
        raise PermissionError("forbidden")
    exam = bundle.get("exam", {}) if isinstance(bundle, dict) else {}
    safe_variant = clean_text(variant, 40) or "A"
    seed = deterministic_exam_seed(
        local_auth_secret(),
        normalize_email((profile or {}).get("email")) or "staff",
        clean_text(exam.get("id"), 80) or "french8-final-exam",
        clean_text(exam.get("version"), 80) + "|simulation|" + safe_variant,
    )
    return {
        "schemaVersion": 1,
        "mode": "simulation",
        "persistence": "none",
        "status": "staff-preview",
        "role": role,
        "variant": safe_variant,
        "state": final_exam_public_state(bundle.get("state", {}), role),
        "exam": final_exam_public_payload(bundle),
        "presentation": final_exam_presentation(exam, seed),
        "attemptSeed": str(seed),
        "simulation": True,
    }


def final_exam_create_attempt(exam, state, student, audio_ready=False):
    student_id = clean_text(student.get("id"), 40)
    attempt_id = secrets.token_urlsafe(18)
    version = clean_text(exam.get("version"), 80)
    seed = deterministic_exam_seed(
        local_auth_secret(),
        student_id,
        clean_text(exam.get("id"), 80),
        version + "|" + attempt_id,
    )
    timestamp = now_iso()
    attempt = {
        "attemptId": attempt_id,
        "attemptSeed": str(seed),
        "examVersion": version,
        "startedAt": timestamp,
        "lastSeenAt": timestamp,
        "audioReady": audio_ready is True,
        "answers": {},
        "revision": 0,
        "draftUpdatedAt": None,
        "status": "in_progress",
        "presentation": final_exam_presentation(exam, seed),
    }
    attempt["timing"] = final_exam_attempt_timing(state, attempt, student_id)
    return attempt


def final_exam_attempt_public(attempt, state, student_id):
    if not isinstance(attempt, dict):
        return None
    timing = final_exam_attempt_timing(state, attempt, student_id)
    answers = attempt.get("answers", {}) if isinstance(attempt.get("answers"), dict) else {}
    revision = attempt.get("revision", 0)
    return {
        "attemptId": attempt.get("attemptId"),
        "attemptSeed": attempt.get("attemptSeed"),
        "examVersion": attempt.get("examVersion"),
        "presentation": attempt.get("presentation", {}),
        "timing": timing,
        "draft": {"answers": answers, "revision": revision, "updatedAt": attempt.get("draftUpdatedAt")},
        "answers": answers,
        "revision": revision,
        "audioReady": attempt.get("audioReady") is True,
        "status": attempt.get("status", "in_progress"),
    }


def final_exam_apply_grade(grades_data, student, submission, evaluation):
    if not isinstance(student, dict) or not isinstance(submission, dict):
        return False
    changed = ensure_evaluation_defaults(grades_data, evaluation)
    grade = clean_grade(submission.get("grade"))
    if grade is not None and student.setdefault("grades", {}).get("finalExam") != grade:
        student["grades"]["finalExam"] = grade
        changed = True
    return changed


def final_exam_sync_released_grades(grades_data, store, evaluation):
    changed = False
    students = {
        clean_text(item.get("id"), 40): item
        for item in grades_data.get("students", [])
        if isinstance(item, dict) and clean_text(item.get("id"), 40)
    }
    for student_id, submission in store.get("submissions", {}).items():
        if final_exam_apply_grade(grades_data, students.get(clean_text(student_id, 40)), submission, evaluation):
            changed = True
    return changed


def final_exam_finalize_attempt(config, grades_data, bundle, store, student, reason="time_expired"):
    student_id = clean_text(student.get("id"), 40)
    submissions = store.setdefault("submissions", {})
    if student_id in submissions:
        return submissions[student_id], False, False
    attempt = store.setdefault("attempts", {}).get(student_id)
    if not isinstance(attempt, dict):
        return None, False, False
    exam = bundle.get("exam", {})
    result = score_final_exam(exam, attempt.get("answers", {}))
    submitted_at = now_iso()
    receipt = submission_receipt_code(
        local_auth_secret(),
        clean_text(exam.get("id"), 80),
        clean_text(exam.get("version"), 80),
        student_id,
        submitted_at,
        clean_text(attempt.get("attemptId"), 120),
    )
    submission = {
        "studentId": student_id,
        "studentName": student.get("fullName", ""),
        "email": normalize_email(student.get("email")),
        "scorePoints": result["scorePoints"],
        "totalPoints": result["totalPoints"],
        "grade": result["grade"],
        "examVersion": clean_text(exam.get("version"), 80),
        "sectionScores": result["sectionScores"],
        "submittedAt": submitted_at,
        "attemptId": attempt.get("attemptId"),
        "receiptCode": receipt,
        "autoSubmitted": reason != "manual",
        "completionReason": reason,
        "answers": result["details"],
    }
    submissions[student_id] = submission
    attempt["status"] = "submitted"
    attempt["submittedAt"] = submitted_at
    attempt["lastSeenAt"] = submitted_at
    grade_changed = final_exam_apply_grade(grades_data, student, submission, config["evaluation"])
    return submission, True, grade_changed


def final_exam_finalize_due_attempts(config, grades_data, bundle, store, force=False, reason="time_expired"):
    changed = False
    grades_changed = False
    state = bundle.get("state", {})
    schedule_closed = (
        isinstance(config, dict)
        and config.get("supportsSchedule") is True
        and final_exam_schedule_status(state) == "closed"
    )
    students = {
        clean_text(item.get("id"), 40): item
        for item in grades_data.get("students", [])
        if isinstance(item, dict) and clean_text(item.get("id"), 40)
    }
    for student_id, attempt in list(store.setdefault("attempts", {}).items()):
        if student_id in store.setdefault("submissions", {}) or not isinstance(attempt, dict):
            continue
        student = students.get(clean_text(student_id, 40))
        if not isinstance(student, dict):
            continue
        due = force or schedule_closed or final_exam_attempt_timing(state, attempt, student_id).get("expired") is True
        if not due:
            continue
        completion_reason = "scheduled_closed" if schedule_closed and not force else reason
        _, saved, grade_saved = final_exam_finalize_attempt(config, grades_data, bundle, store, student, completion_reason)
        changed = changed or saved
        grades_changed = grades_changed or grade_saved
    return changed, grades_changed


def final_exam_weighting_issue(grades_data):
    total = 0.0
    for evaluation in grades_data.get("evaluations", []):
        if not isinstance(evaluation, dict):
            continue
        try:
            total += float(evaluation.get("weight", 0))
        except (TypeError, ValueError):
            return "invalid_weight"
    return None if abs(total - 100) <= 0.001 else "weight_total_" + str(clean_exam_number(total))


def final_exam_authorized(profile, grades_data):
    role = grade_user_role(profile, grades_data)
    student = registered_student_for_profile(profile, grades_data)
    return role, student


def final_exam_preflight_payload(config, profile, grades_data, bundle, store):
    role, student = final_exam_authorized(profile, grades_data)
    if role not in ("admin", "teacher") and not isinstance(student, dict):
        raise PermissionError("student_not_authorized")
    student_id = clean_text(student.get("id"), 40) if isinstance(student, dict) else ""
    check = store.setdefault("preflight", {}).get(student_id, {}) if student_id else {}
    preflight_required = config.get("requiresPreflight", True) is True
    preflight_completed = check.get("audioReady") is True
    integrity = final_exam_integrity(bundle.get("exam", {}), final_exam_audio_path(config))
    return {
        "ok": True,
        "serverReady": True,
        "accountReady": role in ("admin", "teacher") or bool(student_id),
        "registered": bool(student_id),
        "role": role,
        "student": student_public_view(student) if isinstance(student, dict) else None,
        "serverTime": now_iso(),
        "examVersion": clean_text(bundle.get("exam", {}).get("version"), 80),
        "audioReady": preflight_completed,
        "audioCheckedAt": check.get("audioCheckedAt"),
        "preflightRequired": preflight_required,
        "preflightReady": not preflight_required or preflight_completed,
        "preflightAudioUrl": "/api/%s/final-exam/preflight-audio" % config["level"],
        "state": final_exam_public_state(bundle.get("state", {}), role, student_id),
        "integrity": integrity if role in ("admin", "teacher") else {"ok": integrity.get("ok")},
    }


def final_exam_session_action(config, profile, payload):
    grades_data = read_grades_data(config["gradesPath"])
    grades_changed = config["ensureGrades"](grades_data)
    role, student = final_exam_authorized(profile, grades_data)
    if role in ("admin", "teacher") or not isinstance(student, dict):
        if grades_changed:
            write_json_file(config["gradesPath"], grades_data, ".final-exam-grades-")
        return 403, {"error": "student_not_authorized"}
    bundle = config["readBundle"]()
    store = config["readStore"]()
    store_changed, expired_grades = final_exam_finalize_due_attempts(config, grades_data, bundle, store)
    grades_changed = grades_changed or expired_grades
    def finish(status, body, save_store=False):
        if save_store or store_changed:
            config["writeStore"](store)
        if grades_changed:
            write_json_file(config["gradesPath"], grades_data, ".final-exam-grades-")
        return status, body
    state = bundle.get("state", {})
    student_id = clean_text(student.get("id"), 40)
    scope_error = final_exam_bridge_attempt_error(
        profile, config, student, bundle, store, allow_submission=True
    )
    if scope_error:
        return finish(*scope_error)
    existing_submission = store.get("submissions", {}).get(student_id)
    if isinstance(existing_submission, dict):
        return finish(409, {
            "error": "already_submitted",
            "result": french1_final_exam_submission_public(existing_submission, state),
        })
    if state.get("isOpen") is not True:
        return finish(403, {"error": "exam_closed", "state": final_exam_public_state(state, role, student_id)})
    exam = bundle.get("exam", {})
    attempt = final_exam_matching_attempt(store, student, exam)
    if not isinstance(attempt, dict):
        if config.get("requiresPreflight", True) is True:
            preflight = store.setdefault("preflight", {}).get(student_id)
            if not isinstance(preflight, dict) or preflight.get("audioReady") is not True:
                return finish(409, {"error": "preflight_required"})
        # ``audioReady`` in the session payload refers to the protected exam
        # audio and must never be trusted to bypass or impersonate preflight.
        attempt = final_exam_create_attempt(exam, state, student, False)
        store["attempts"][student_id] = attempt
        final_exam_append_event(store, "session_started", profile, student, {"attemptId": attempt.get("attemptId")})
        store_changed = True
    else:
        attempt["lastSeenAt"] = now_iso()
        if payload.get("audioReady") is True and attempt.get("audioReady") is not True:
            attempt["audioReady"] = True
        store_changed = True
    public = final_exam_attempt_public(attempt, state, student_id)
    public.update({
        "ok": True,
        "state": final_exam_public_state(state, role, student_id),
        "exam": final_exam_public_payload(bundle),
    })
    public.update(final_exam_access_credentials(profile, config, attempt, exam))
    return finish(200, public, save_store=True)


def final_exam_get_draft(config, profile):
    grades_data = read_grades_data(config["gradesPath"])
    grades_changed = config["ensureGrades"](grades_data)
    role, student = final_exam_authorized(profile, grades_data)
    if role in ("admin", "teacher") or not isinstance(student, dict):
        if grades_changed:
            write_json_file(config["gradesPath"], grades_data, ".final-exam-grades-")
        return 403, {"error": "student_not_authorized"}
    bundle = config["readBundle"]()
    store = config["readStore"]()
    store_changed, expired_grades = final_exam_finalize_due_attempts(config, grades_data, bundle, store)
    grades_changed = grades_changed or expired_grades
    def finish(status, body):
        if store_changed:
            config["writeStore"](store)
        if grades_changed:
            write_json_file(config["gradesPath"], grades_data, ".final-exam-grades-")
        return status, body
    student_id = clean_text(student.get("id"), 40)
    scope_error = final_exam_bridge_attempt_error(
        profile, config, student, bundle, store, allow_submission=True
    )
    if scope_error:
        return finish(*scope_error)
    submitted = store.get("submissions", {}).get(student_id)
    if isinstance(submitted, dict):
        return finish(409, {"error": "already_submitted", "result": french1_final_exam_submission_public(submitted, bundle.get("state", {}))})
    attempt = store.get("attempts", {}).get(student_id)
    if not isinstance(attempt, dict):
        return finish(404, {"error": "attempt_not_started"})
    public = final_exam_attempt_public(attempt, bundle.get("state", {}), student_id)
    public["answers"] = attempt.get("answers", {})
    public["version"] = public.get("examVersion")
    return finish(200, public)


def final_exam_put_draft(config, profile, payload):
    grades_data = read_grades_data(config["gradesPath"])
    grades_changed = config["ensureGrades"](grades_data)
    role, student = final_exam_authorized(profile, grades_data)
    if role in ("admin", "teacher") or not isinstance(student, dict):
        if grades_changed:
            write_json_file(config["gradesPath"], grades_data, ".final-exam-grades-")
        return 403, {"error": "student_not_authorized"}
    bundle = config["readBundle"]()
    store = config["readStore"]()
    store_changed, expired_grades = final_exam_finalize_due_attempts(config, grades_data, bundle, store)
    grades_changed = grades_changed or expired_grades
    def finish(status, body, save_store=False):
        if save_store or store_changed:
            config["writeStore"](store)
        if grades_changed:
            write_json_file(config["gradesPath"], grades_data, ".final-exam-grades-")
        return status, body
    student_id = clean_text(student.get("id"), 40)
    scope_error = final_exam_bridge_attempt_error(
        profile, config, student, bundle, store, allow_submission=True
    )
    if scope_error:
        return finish(*scope_error)
    if student_id in store.get("submissions", {}):
        return finish(409, {"error": "already_submitted"})
    attempt = store.get("attempts", {}).get(student_id)
    if not isinstance(attempt, dict):
        return finish(404, {"error": "attempt_not_started"})
    if clean_text(payload.get("attemptId"), 120) != clean_text(attempt.get("attemptId"), 120):
        return finish(409, {"error": "attempt_mismatch"})
    version = clean_text(payload.get("examVersion") or payload.get("version"), 80)
    if version != clean_text(bundle.get("exam", {}).get("version"), 80):
        return finish(409, {"error": "exam_version_changed", "examVersion": bundle.get("exam", {}).get("version")})
    raw_answers = payload.get("answers")
    question_count = final_exam_question_count(bundle.get("exam", {}))
    if not isinstance(raw_answers, dict) or len(raw_answers) > max(10, question_count + 5):
        return finish(400, {"error": "invalid_draft"})
    try:
        revision = int(payload.get("revision", -1))
    except (TypeError, ValueError):
        revision = -1
    current_revision = int(attempt.get("revision", 0) or 0)
    if revision != current_revision:
        return finish(409, {"error": "stale_draft", "revision": current_revision, "draft": attempt.get("answers", {}), "answers": attempt.get("answers", {})})
    timing = final_exam_attempt_timing(bundle.get("state", {}), attempt, student_id)
    if timing.get("expired") is True:
        submission, saved, grade_saved = final_exam_finalize_attempt(config, grades_data, bundle, store, student, "time_expired")
        grades_changed = grades_changed or grade_saved
        return finish(409, {"error": "time_expired", "result": french1_final_exam_submission_public(submission, bundle.get("state", {}))}, save_store=saved)
    validation = validate_partial_draft(bundle.get("exam", {}), {"answers": raw_answers})
    if validation.get("unknownQuestionIds") or validation.get("invalidAnswerIds"):
        return finish(400, {
            "error": "invalid_draft",
            "unknownQuestionIds": validation.get("unknownQuestionIds"),
            "invalidAnswerIds": validation.get("invalidAnswerIds"),
        })
    attempt["answers"] = validation["answers"]
    attempt["revision"] = current_revision + 1
    attempt["draftUpdatedAt"] = now_iso()
    attempt["lastSeenAt"] = attempt["draftUpdatedAt"]
    if isinstance(payload.get("audioReady"), bool):
        attempt["audioReady"] = payload.get("audioReady")
    return finish(200, {
        "ok": True,
        "attemptId": attempt.get("attemptId"),
        "draft": attempt["answers"],
        "revision": attempt["revision"],
        "savedAt": attempt["draftUpdatedAt"],
        "answeredCount": validation["answeredCount"],
        "timing": timing,
    }, save_store=True)


def final_exam_monitor_payload(config, grades_data, bundle, store):
    state = bundle.get("state", {})
    total_questions = final_exam_question_count(bundle.get("exam", {}))
    preflight_required = config.get("requiresPreflight", True) is True
    rows = []
    for student in grades_data.get("students", []):
        if not isinstance(student, dict):
            continue
        student_id = clean_text(student.get("id"), 40)
        submission = store.get("submissions", {}).get(student_id)
        attempt = store.get("attempts", {}).get(student_id)
        preflight = store.get("preflight", {}).get(student_id, {})
        if isinstance(submission, dict):
            status = "submitted_auto" if submission.get("autoSubmitted") is True else "submitted"
        elif isinstance(attempt, dict):
            status = "in_progress"
        else:
            status = "not_started"
        answers = attempt.get("answers", {}) if isinstance(attempt, dict) and isinstance(attempt.get("answers"), dict) else {}
        timing = final_exam_attempt_timing(state, attempt, student_id) if isinstance(attempt, dict) and not isinstance(submission, dict) else None
        rows.append({
            "studentId": student_id,
            "studentName": clean_text(student.get("fullName"), 160),
            "email": normalize_email(student.get("email")),
            "status": status,
            "event": (
                "submitted_auto" if isinstance(submission, dict) and submission.get("autoSubmitted") is True
                else "submitted" if isinstance(submission, dict)
                else "audio_ready" if isinstance(attempt, dict) and attempt.get("audioReady") is True
                else "progress" if isinstance(attempt, dict) and answers
                else "started" if isinstance(attempt, dict)
                else "pending"
            ),
            "preflightRequired": preflight_required,
            "preflightReady": not preflight_required or preflight.get("audioReady") is True,
            "audioReady": attempt.get("audioReady") is True if isinstance(attempt, dict) else False,
            "answeredCount": len(answers),
            "totalQuestions": total_questions,
            "startedAt": attempt.get("startedAt") if isinstance(attempt, dict) else None,
            "lastSeenAt": attempt.get("lastSeenAt") if isinstance(attempt, dict) else None,
            "draftUpdatedAt": attempt.get("draftUpdatedAt") if isinstance(attempt, dict) else None,
            "timing": timing,
            "remainingSeconds": timing.get("remainingSeconds") if isinstance(timing, dict) else None,
            "draftSaved": bool(isinstance(attempt, dict) and attempt.get("draftUpdatedAt")),
            "extraMinutes": (state.get("extraMinutesByStudent", {}) or {}).get(student_id, 0),
            "result": french1_final_exam_submission_public(submission, state, is_staff=True),
        })
    counts = {"total": len(rows), "notStarted": 0, "inProgress": 0, "submitted": 0, "autoSubmitted": 0}
    for row in rows:
        if row["status"] == "not_started":
            counts["notStarted"] += 1
        elif row["status"] == "in_progress":
            counts["inProgress"] += 1
        else:
            counts["submitted"] += 1
            if row["status"] == "submitted_auto":
                counts["autoSubmitted"] += 1
    return {
        "ok": True,
        "serverTime": now_iso(),
        "preflightRequired": preflight_required,
        "state": final_exam_public_state(state, "teacher"),
        "counts": counts,
        "students": rows,
        "integrity": final_exam_integrity(bundle.get("exam", {}), final_exam_audio_path(config)),
        "weightingIssue": final_exam_weighting_issue(grades_data),
    }


def final_exam_submit_action(config, profile, payload):
    grades_data = read_grades_data(config["gradesPath"])
    grades_changed = config["ensureGrades"](grades_data)
    role, student = final_exam_authorized(profile, grades_data)
    if role in ("admin", "teacher") or not isinstance(student, dict):
        if grades_changed:
            write_json_file(config["gradesPath"], grades_data, ".final-exam-grades-")
        return 403, {"error": "student_not_authorized"}
    bundle = config["readBundle"]()
    store = config["readStore"]()
    store_changed, due_grades = final_exam_finalize_due_attempts(config, grades_data, bundle, store)
    grades_changed = grades_changed or due_grades
    def finish(status, body, save_store=False):
        if save_store or store_changed:
            config["writeStore"](store)
        if grades_changed:
            write_json_file(config["gradesPath"], grades_data, ".final-exam-grades-")
        return status, body
    state = bundle.get("state", {})
    student_id = clean_text(student.get("id"), 40)
    scope_error = final_exam_bridge_attempt_error(
        profile, config, student, bundle, store, allow_submission=True
    )
    if scope_error:
        return finish(*scope_error)
    client_submission_id = clean_text(payload.get("clientSubmissionId"), 120)
    request_hash = hashlib.sha256(json.dumps({
        "attemptId": clean_text(payload.get("attemptId"), 120),
        "examVersion": clean_text(payload.get("examVersion") or payload.get("version"), 80),
        "answers": payload.get("answers") if isinstance(payload.get("answers"), dict) else {},
        "autoSubmit": payload.get("autoSubmit") is True,
    }, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    idempotency = store.setdefault("idempotency", {})
    if not isinstance(idempotency, dict):
        idempotency = {}
        store["idempotency"] = idempotency
    idempotency_key = student_id + ":" + client_submission_id if client_submission_id else ""
    prior_idempotency = idempotency.get(idempotency_key) if idempotency_key else None
    if isinstance(prior_idempotency, dict) and not hmac.compare_digest(
        clean_text(prior_idempotency.get("requestHash"), 80), request_hash
    ):
        return finish(409, {"error": "idempotency_conflict"})
    existing = store.get("submissions", {}).get(student_id)
    if isinstance(existing, dict):
        grades_changed = final_exam_apply_grade(grades_data, student, existing, config["evaluation"]) or grades_changed
        if isinstance(prior_idempotency, dict) and clean_text(prior_idempotency.get("receiptCode"), 120) == clean_text(existing.get("receiptCode"), 120):
            return finish(200, {
                "ok": True,
                "duplicate": True,
                "result": french1_final_exam_submission_public(existing, state),
            })
        if payload.get("autoSubmit") is True and existing.get("autoSubmitted") is True:
            return finish(200, {"ok": True, "duplicate": True, "autoSubmitted": True, "result": french1_final_exam_submission_public(existing, state)})
        return finish(409, {"error": "already_submitted", "result": french1_final_exam_submission_public(existing, state)})
    if state.get("isOpen") is not True:
        return finish(403, {"error": "exam_closed", "state": final_exam_public_state(state, role, student_id)})
    exam = bundle.get("exam", {})
    server_version = clean_text(exam.get("version"), 80)
    client_version = clean_text(payload.get("examVersion") or payload.get("version"), 80)
    if client_version != server_version:
        return finish(409, {"error": "exam_version_changed", "examVersion": server_version})
    attempt = store.setdefault("attempts", {}).get(student_id)
    if not isinstance(attempt, dict):
        return finish(409, {"error": "attempt_not_started"})
    supplied_attempt_id = clean_text(payload.get("attemptId"), 120)
    if supplied_attempt_id and supplied_attempt_id != clean_text(attempt.get("attemptId"), 120):
        return finish(409, {"error": "attempt_mismatch"})
    if "revision" in payload:
        try:
            submitted_revision = int(payload.get("revision"))
        except (TypeError, ValueError):
            return finish(400, {"error": "invalid_revision"})
        current_revision = int(attempt.get("revision", 0) or 0)
        if submitted_revision != current_revision:
            return finish(409, {
                "error": "stale_draft",
                "revision": current_revision,
                "draft": attempt.get("answers", {}),
                "answers": attempt.get("answers", {}),
            })
    timing = final_exam_attempt_timing(state, attempt, student_id)
    if timing.get("expired") is True:
        submission, saved, grade_saved = final_exam_finalize_attempt(config, grades_data, bundle, store, student, "time_expired")
        grades_changed = grades_changed or grade_saved
        return finish(200, {"ok": True, "autoSubmitted": True, "result": french1_final_exam_submission_public(submission, state)}, save_store=saved)
    if payload.get("autoSubmit") is True:
        return finish(409, {"error": "timer_active", "timing": timing})
    try:
        validate_final_exam_answers(exam, payload.get("answers"))
    except ValueError as error:
        return finish(400, {"error": str(error)})
    attempt["answers"] = validate_partial_draft(exam, {"answers": payload.get("answers")})["answers"]
    attempt["lastSeenAt"] = now_iso()
    submission, saved, grade_saved = final_exam_finalize_attempt(config, grades_data, bundle, store, student, "manual")
    if idempotency_key:
        idempotency[idempotency_key] = {
            "requestHash": request_hash,
            "receiptCode": clean_text(submission.get("receiptCode"), 120),
            "attemptId": clean_text(submission.get("attemptId"), 120),
            "createdAt": now_iso(),
        }
    final_exam_append_event(store, "submission_recorded", profile, student, {"attemptId": attempt.get("attemptId"), "receiptCode": submission.get("receiptCode")})
    grades_changed = grades_changed or grade_saved
    return finish(200, {"ok": True, "result": french1_final_exam_submission_public(submission, state)}, save_store=True)


def final_exam_update_state(config, profile, payload):
    grades_data = read_grades_data(config["gradesPath"])
    grades_changed = config["ensureGrades"](grades_data)
    role, _ = final_exam_authorized(profile, grades_data)
    if role not in ("admin", "teacher"):
        if grades_changed:
            write_json_file(config["gradesPath"], grades_data, ".final-exam-grades-")
        return 403, {"error": "forbidden"}
    bundle = config["readBundle"]()
    state = bundle.setdefault("state", {})
    supports_schedule = config.get("supportsSchedule") is True
    opening_gate_reset_reason = ""
    schedule_refreshed = (
        final_exam_refresh_schedule_state(state, allow_open=False)
        if supports_schedule
        else False
    )
    store = config["readStore"]()
    store_changed, due_grades = final_exam_finalize_due_attempts(config, grades_data, bundle, store)
    grades_changed = grades_changed or due_grades
    bundle_changed = schedule_refreshed

    def persist_documents():
        nonlocal bundle_changed, store_changed
        write_documents = config.get("writeDocuments")
        if bundle_changed and store_changed and callable(write_documents):
            write_documents(bundle, store)
            bundle_changed = False
            store_changed = False
        if bundle_changed:
            config["writeBundle"](bundle)
            bundle_changed = False
        if store_changed:
            config["writeStore"](store)
            store_changed = False

    def fail(status, body):
        persist_documents()
        if grades_changed:
            write_json_file(config["gradesPath"], grades_data, ".final-exam-grades-")
        return status, body

    action = clean_text(payload.get("action"), 40).lower()
    has_opens_value = payload.get("opensAt") not in (None, "")
    has_closes_value = payload.get("closesAt") not in (None, "")
    schedule_requested = supports_schedule and (
        action in ("schedule", "program") or has_opens_value or has_closes_value
    )
    if schedule_requested and (not has_opens_value or not has_closes_value):
        return fail(400, {"error": "invalid_schedule", "reason": "opens_and_closes_required"})

    proposed_schedule = None
    if schedule_requested:
        opens_at = final_exam_parse_utc(payload.get("opensAt"))
        closes_at = final_exam_parse_utc(payload.get("closesAt"))
        if not opens_at or not closes_at or closes_at <= opens_at:
            return fail(400, {"error": "invalid_schedule", "reason": "invalid_window"})
        if closes_at <= datetime.now(timezone.utc):
            return fail(400, {"error": "invalid_schedule", "reason": "window_elapsed"})
        proposed_schedule = dict(state)
        proposed_schedule.update({
            "scheduleEnabled": True,
            "opensAt": final_exam_iso_utc(opens_at),
            "closesAt": final_exam_iso_utc(closes_at),
        })
        final_exam_refresh_schedule_state(proposed_schedule)

    manual_state_requested = isinstance(payload.get("isOpen"), bool) or action in ("open_now", "close_now", "open", "close")
    if schedule_requested:
        desired_open = proposed_schedule.get("isOpen") is True
    elif action in ("open_now", "open"):
        desired_open = True
    elif action in ("close_now", "close"):
        desired_open = False
    elif isinstance(payload.get("isOpen"), bool):
        desired_open = payload.get("isOpen") is True
    else:
        desired_open = state.get("isOpen") is True

    active_ids = [
        clean_text(student_id, 40)
        for student_id, attempt in store.get("attempts", {}).items()
        if isinstance(attempt, dict) and student_id not in store.get("submissions", {})
    ]
    currently_open = state.get("isOpen") is True
    state_change_requested = schedule_requested or manual_state_requested
    if state_change_requested and not desired_open and currently_open and active_ids and payload.get("confirmClose") is not True:
        return fail(409, {"error": "active_attempts", "activeAttempts": len(active_ids), "studentIds": active_ids})
    if "durationMinutes" in payload:
        try:
            duration = int(payload.get("durationMinutes"))
        except (TypeError, ValueError):
            return fail(400, {"error": "invalid_duration"})
        if duration < 10 or duration > 240:
            return fail(400, {"error": "invalid_duration"})
        if active_ids and duration != int(state.get("durationMinutes", 90) or 90):
            return fail(409, {"error": "duration_locked", "activeAttempts": len(active_ids)})
        if state.get("durationMinutes") != duration:
            state["durationMinutes"] = duration
            bundle_changed = True

    extra_payload = payload.get("extraTime") if isinstance(payload.get("extraTime"), dict) else payload
    if "studentId" in extra_payload or "extraMinutes" in extra_payload:
        supplied_student = clean_text(extra_payload.get("studentId"), 160)
        try:
            extra_minutes = int(extra_payload.get("extraMinutes"))
        except (TypeError, ValueError):
            return fail(400, {"error": "invalid_extra_time"})
        matched_roster_student = next(
            (
                item for item in grades_data.get("students", [])
                if isinstance(item, dict) and (
                    clean_text(item.get("id"), 40) == supplied_student
                    or email_matches_student(item, normalize_email(supplied_student))
                )
            ),
            None,
        )
        student_id = clean_text(matched_roster_student.get("id"), 40) if isinstance(matched_roster_student, dict) else ""
        if not student_id or not 0 <= extra_minutes <= 180:
            return fail(400, {"error": "invalid_extra_time"})
        extras = state.setdefault("extraMinutesByStudent", {})
        if extra_minutes:
            extras[student_id] = extra_minutes
        else:
            extras.pop(student_id, None)
        bundle_changed = True
        final_exam_append_event(store, "extra_time_updated", profile, None, {"targetStudentId": student_id, "extraMinutes": extra_minutes})
        store_changed = True

    if "releaseResults" in payload:
        requested_release = payload.get("releaseResults") is True
        if state.get("releaseResults") is True and not requested_release:
            return fail(409, {"error": "results_release_irreversible"})
        if requested_release and currently_open:
            return fail(409, {"error": "exam_active"})
        if requested_release and state.get("releaseResults") is not True and not state.get("closedAt"):
            return fail(409, {"error": "exam_not_completed"})
        if requested_release and state.get("releaseResults") is not True and not any(
            isinstance(item, dict) for item in store.get("submissions", {}).values()
        ):
            return fail(409, {"error": "no_submissions"})
        if requested_release and state.get("releaseResults") is not True:
            state["releaseResults"] = True
            state["releasedAt"] = now_iso()
            state["releasedBy"] = normalize_email(profile.get("email"))
            bundle_changed = True
            final_exam_append_event(store, "results_released", profile)
            store_changed = True

    needs_readiness = schedule_requested or (state_change_requested and desired_open and not currently_open)
    if needs_readiness:
        if state.get("releaseResults") is True:
            return fail(409, {"error": "results_already_released"})
        weighting_issue = final_exam_weighting_issue(grades_data)
        if weighting_issue:
            return fail(409, {"error": "gradebook_not_ready", "weightingIssue": weighting_issue})
        integrity = final_exam_integrity(bundle.get("exam", {}), final_exam_audio_path(config))
        if not integrity.get("ok"):
            return fail(409, {"error": "exam_not_ready", "integrity": integrity})
        health_check = config.get("healthCheck")
        if callable(health_check):
            health = health_check(config, grades_data, bundle, store, record_alerts=True)
            if health.get("readyToOpen") is not True:
                return fail(409, {
                    "error": "exam_health_check_failed",
                    "health": health,
                    "blockingIssues": health.get("blockingIssues", []),
                })
            if schedule_requested and health.get("schedulerReady") is not True:
                return fail(409, {
                    "error": "exam_health_check_failed",
                    "reason": "scheduler_not_ready",
                    "health": health,
                })

    timestamp = now_iso()
    if schedule_requested:
        opening_gate_reset_reason = "scheduled_window_reprogrammed"
        state.update({
            "scheduleEnabled": True,
            "opensAt": proposed_schedule.get("opensAt"),
            "closesAt": proposed_schedule.get("closesAt"),
            "scheduledAt": timestamp,
            "scheduledBy": normalize_email(profile.get("email")),
        })
        state.pop("openingGate", None)
        final_exam_refresh_schedule_state(state)
        state["schedulerObservedStatus"] = final_exam_schedule_status(state)
        desired_open = state.get("isOpen") is True
        bundle_changed = True
        final_exam_append_event(store, "exam_scheduled", profile, None, {
            "opensAt": state.get("opensAt"),
            "closesAt": state.get("closesAt"),
        })
        store_changed = True
    elif supports_schedule and manual_state_requested:
        opening_gate_reset_reason = "scheduled_window_disabled_by_staff"
        state.update({
            "scheduleEnabled": False,
            "opensAt": None,
            "closesAt": None,
            "scheduledAt": None,
            "scheduledBy": None,
        })
        state.pop("scheduleStatus", None)
        state.pop("openingGate", None)
        state["schedulerObservedStatus"] = "manual_open" if desired_open else "manual_closed"
        bundle_changed = True

    manual_override = supports_schedule and manual_state_requested and not schedule_requested
    if desired_open and (not currently_open or manual_override):
        timestamp = now_iso()
        state["isOpen"] = True
        state["openedAt"] = state.get("opensAt") if schedule_requested else timestamp
        state["openedBy"] = normalize_email(profile.get("email"))
        state["closedAt"] = None
        state["updatedAt"] = timestamp
        bundle_changed = True
        final_exam_append_event(store, "exam_opened" if not schedule_requested else "scheduled_window_opened", profile)
        store_changed = True
    elif not desired_open and (currently_open or manual_override):
        if active_ids:
            saved, saved_grades = final_exam_finalize_due_attempts(
                config, grades_data, bundle, store, force=True, reason="teacher_closed"
            )
            store_changed = store_changed or saved
            grades_changed = grades_changed or saved_grades
        timestamp = now_iso()
        state["isOpen"] = False
        if schedule_requested:
            final_exam_refresh_schedule_state(state)
        else:
            state["closedAt"] = timestamp
        state["updatedAt"] = timestamp
        bundle_changed = True
        final_exam_append_event(store, "exam_closed", profile, None, {"forcedAttempts": len(active_ids)})
        store_changed = True

    if state.get("releaseResults") is True:
        grades_changed = final_exam_sync_released_grades(grades_data, store, config["evaluation"]) or grades_changed
    if bundle_changed:
        state["revision"] = int(state.get("revision", 0) or 0) + 1
        state["updatedAt"] = now_iso()
    persist_documents()
    if grades_changed:
        write_json_file(config["gradesPath"], grades_data, ".final-exam-grades-")
    if config.get("level") == "french8":
        if opening_gate_reset_reason:
            french8_final_exam_sync_opening_gate_alert(
                config,
                {},
                False,
                resolution=opening_gate_reset_reason,
            )
            next_runtime_gate_status = (
                "pending"
                if schedule_requested and final_exam_schedule_status(state) == "scheduled"
                else ("ready" if schedule_requested and state.get("isOpen") is True else "idle")
            )
            FRENCH8_FINAL_EXAM_RUNTIME_STATUS.update({
                "scheduledOpeningGateStatus": next_runtime_gate_status,
                "scheduledOpeningGateCheckedAt": (
                    timestamp if next_runtime_gate_status == "ready" else None
                ),
                "scheduledOpeningBlockingIssues": [],
                "scheduledOpeningLastError": "",
            })
        FRENCH8_FINAL_EXAM_SCHEDULER_WAKE.set()
    return 200, {
        "ok": True,
        "state": final_exam_public_state(state, role),
        "weightingIssue": final_exam_weighting_issue(grades_data),
    }


def french8_final_exam_scheduler_opening_health(config, grades_data, bundle, store):
    """Run the current-data health gate and normalize failures as closed state."""

    health_check = config.get("healthCheck") if isinstance(config, dict) else None
    if not callable(health_check):
        return {
            "readyToOpen": False,
            "status": "error",
            "blockingIssues": ["health_check"],
            "error": "opening_health_check_unavailable",
        }
    try:
        health = health_check(
            config, grades_data, bundle, store, record_alerts=True
        )
    except Exception as error:
        return {
            "readyToOpen": False,
            "status": "error",
            "blockingIssues": ["health_check"],
            "error": clean_text(error, 300) or error.__class__.__name__,
        }
    if not isinstance(health, dict):
        return {
            "readyToOpen": False,
            "status": "error",
            "blockingIssues": ["health_check"],
            "error": "opening_health_check_invalid_response",
        }
    # ``schedulerReady`` is intentionally not required here.  This function is
    # running inside the scheduler tick; asking its previously persisted
    # heartbeat to authorize the current tick would create a recursive gate.
    return health


def french8_final_exam_sync_opening_gate_alert(
    config,
    gate,
    blocked,
    resolution="scheduled_opening_health_recovered",
):
    """Best-effort explicit alert in addition to component health alerts."""

    repository_factory = config.get("repository") if isinstance(config, dict) else None
    if not callable(repository_factory):
        return
    try:
        repository = repository_factory()
        alert_key = "scheduled_opening_gate"
        existing = repository.get_alert(alert_key)
        if blocked:
            context = {
                "healthStatus": clean_text(gate.get("healthStatus"), 40),
                "blockingIssues": list(gate.get("blockingIssues", [])),
                "lastError": clean_text(gate.get("lastError"), 300),
            }
            if (
                existing is None
                or existing.get("status") == "resolved"
                or existing.get("context") != context
            ):
                repository.record_alert(
                    alert_key,
                    "critical",
                    message="L'ouverture programmee reste fermee: le controle de sante n'est pas pret.",
                    context=context,
                )
        elif existing and existing.get("status") != "resolved":
            repository.resolve_alert(
                alert_key,
                "system",
                resolution=clean_text(resolution, 300)
                or "scheduled_opening_health_recovered",
            )
    except Exception:
        # The persisted bundle/store event remains the authoritative audit.  A
        # repository failure is itself returned by the health gate and opening
        # therefore stays fail-closed.
        return


def french8_final_exam_scheduler_tick(config=None, now=None):
    """Materialize scheduled transitions and submissions without HTTP traffic."""

    config = config or final_exam_level_config("french8")
    tick_at = final_exam_iso_utc(now) or now_iso()
    with data_lock:
        grades_data = read_grades_data(config["gradesPath"])
        grades_changed = config["ensureGrades"](grades_data)
        bundle = config["readBundle"]()
        state = bundle.setdefault("state", {})
        store = config["readStore"]()
        previous_observed = clean_text(state.get("schedulerObservedStatus"), 40)
        schedule_status = final_exam_schedule_status(state, now)
        previous_gate = state.get("openingGate") if isinstance(state.get("openingGate"), dict) else {}
        gate_health = None
        gate_blocked = False
        gate_changed = False
        gate_lifecycle_changed = False
        opening_requested = (
            state.get("scheduleEnabled") is True
            and schedule_status == "open"
            and state.get("isOpen") is not True
        )

        if opening_requested:
            gate_health = french8_final_exam_scheduler_opening_health(
                config, grades_data, bundle, store
            )
            blocking_issues = sorted({
                clean_text(item, 80)
                for item in gate_health.get("blockingIssues", [])
                if clean_text(item, 80)
            })
            health_error = clean_text(gate_health.get("error"), 300)
            if gate_health.get("readyToOpen") is True:
                schedule_changed = final_exam_refresh_schedule_state(
                    state, now, allow_open=True
                )
                next_gate = {
                    "status": "ready",
                    "checkedAt": tick_at,
                    "blockedAt": previous_gate.get("blockedAt"),
                    "recoveredAt": tick_at if previous_gate.get("status") == "blocked" else None,
                    "healthStatus": clean_text(gate_health.get("status"), 40) or "ok",
                    "blockingIssues": [],
                    "lastError": "",
                }
                gate_changed = next_gate != previous_gate
                state["openingGate"] = next_gate
            else:
                gate_blocked = True
                if not blocking_issues:
                    blocking_issues = ["health_check"]
                schedule_changed = final_exam_refresh_schedule_state(
                    state, now, allow_open=False
                )
                gate_signature = {
                    "status": "blocked",
                    "healthStatus": clean_text(gate_health.get("status"), 40) or "blocked",
                    "blockingIssues": blocking_issues,
                    "lastError": health_error,
                }
                previous_signature = {
                    key: previous_gate.get(key)
                    for key in ("status", "healthStatus", "blockingIssues", "lastError")
                }
                gate_changed = gate_signature != previous_signature
                if gate_changed:
                    state["openingGate"] = dict(
                        gate_signature,
                        checkedAt=tick_at,
                        blockedAt=previous_gate.get("blockedAt") or tick_at,
                        recoveredAt=None,
                    )
                else:
                    # ``checkedAt`` is operational evidence, not a semantic
                    # state transition.  Keep the fresh value for this tick;
                    # the runtime health snapshot retains it without writing
                    # a new bundle/audit row every five seconds.
                    state["openingGate"] = dict(previous_gate, checkedAt=tick_at)
        else:
            # Scheduled closes are always materialized and never depend on the
            # opening readiness gate.
            schedule_changed = final_exam_refresh_schedule_state(
                state, now, allow_open=True
            )
            if (
                state.get("scheduleEnabled") is True
                and schedule_status == "closed"
                and previous_gate.get("status") in ("blocked", "ready")
            ):
                # Preserve the useful timestamps but make it explicit that a
                # previous opening block is historical once the window ends.
                state["openingGate"] = dict(
                    previous_gate,
                    status="closed",
                    inactiveAt=tick_at,
                    blockingIssues=[],
                    lastError="",
                )
                gate_lifecycle_changed = state["openingGate"] != previous_gate

        if gate_lifecycle_changed:
            schedule_changed = True

        observed_status = "open_blocked" if gate_blocked else schedule_status
        observation_changed = (
            state.get("scheduleEnabled") is True
            and observed_status != previous_observed
        )
        transition = observation_changed and observed_status != "open_blocked"
        store_changed = False
        if observation_changed:
            event_name = {
                "open": "scheduled_window_opened",
                "open_blocked": "scheduled_window_open_blocked",
                "closed": "scheduled_window_closed",
                "scheduled": "scheduled_window_waiting",
                "invalid": "scheduled_window_invalid",
            }.get(observed_status, "scheduled_window_updated")
            detail = {
                "scheduleStatus": schedule_status,
                "observedStatus": observed_status,
            }
            if gate_health is not None:
                detail.update({
                    "healthStatus": clean_text(gate_health.get("status"), 40),
                    "blockingIssues": list(state.get("openingGate", {}).get("blockingIssues", [])),
                    "healthError": clean_text(gate_health.get("error"), 300),
                    "recoveredFromHealthBlock": previous_observed == "open_blocked",
                })
            final_exam_append_event(store, event_name, extra=detail)
            state["schedulerObservedStatus"] = observed_status
            store_changed = True
            schedule_changed = True
        elif gate_changed:
            final_exam_append_event(store, "scheduled_window_open_block_updated", extra={
                "scheduleStatus": schedule_status,
                "healthStatus": clean_text(gate_health.get("status"), 40) if gate_health else "",
                "blockingIssues": list(state.get("openingGate", {}).get("blockingIssues", [])),
                "healthError": clean_text(gate_health.get("error"), 300) if gate_health else "",
            })
            store_changed = True
            schedule_changed = True
        elif gate_lifecycle_changed:
            final_exam_append_event(store, "scheduled_opening_gate_inactivated", extra={
                "scheduleStatus": schedule_status,
                "previousGateStatus": clean_text(previous_gate.get("status"), 40),
                "gateStatus": clean_text(state.get("openingGate", {}).get("status"), 40),
            })
            store_changed = True
            schedule_changed = True

        if observation_changed or gate_changed or gate_lifecycle_changed:
            state["updatedAt"] = tick_at
            state["revision"] = int(state.get("revision", 0) or 0) + 1
        finalized, finalized_grades = final_exam_finalize_due_attempts(
            config, grades_data, bundle, store
        )
        if finalized:
            final_exam_append_event(store, "scheduled_attempts_finalized", extra={
                "scheduleStatus": observed_status,
                "submissionCount": len(store.get("submissions", {})),
            })
            store_changed = True
        grades_changed = grades_changed or finalized_grades
        write_documents = config.get("writeDocuments")
        store_persisted = False
        if schedule_changed and (store_changed or finalized) and callable(write_documents):
            write_documents(bundle, store)
            schedule_changed = False
            store_changed = False
            store_persisted = True
        if schedule_changed:
            config["writeBundle"](bundle)
        if (store_changed or finalized) and not store_persisted:
            config["writeStore"](store)
        if (
            gate_health is not None
            or gate_lifecycle_changed
            or (previous_gate.get("status") == "blocked" and not gate_blocked)
        ):
            french8_final_exam_sync_opening_gate_alert(
                config,
                state.get("openingGate") if isinstance(state.get("openingGate"), dict) else {},
                gate_blocked,
                resolution=(
                    "scheduled_window_ended"
                    if schedule_status == "closed"
                    else "scheduled_opening_health_recovered"
                ),
            )
        if grades_changed:
            write_json_file(config["gradesPath"], grades_data, ".final-exam-grades-")
            grades_changed = False
        outbox = french8_final_exam_reconcile_grade_outbox(config, grades_data, store)
        public_state = final_exam_public_state(state, "teacher")
        persisted_gate = state.get("openingGate") if isinstance(state.get("openingGate"), dict) else {}
    timestamp = now_iso()
    FRENCH8_FINAL_EXAM_RUNTIME_STATUS.update({
        "schedulerLastTickAt": timestamp,
        "schedulerLastSuccessAt": timestamp,
        "schedulerLastError": "",
        "schedulerConsecutiveFailures": 0,
        "scheduledOpeningGateStatus": (
            "blocked"
            if gate_blocked
            else (
                "ready"
                if gate_health is not None
                else ("pending" if schedule_status == "scheduled" else "idle")
            )
        ),
        "scheduledOpeningGateCheckedAt": (
            persisted_gate.get("checkedAt")
            if persisted_gate.get("status") in ("blocked", "ready")
            else None
        ),
        "scheduledOpeningBlockingIssues": list(
            persisted_gate.get("blockingIssues", [])
        ) if gate_blocked else [],
        "scheduledOpeningLastError": (
            clean_text(gate_health.get("error"), 300)
            if gate_blocked and gate_health is not None
            else ""
        ),
    })
    return {
        "ok": True,
        "transition": transition,
        "observationChanged": observation_changed,
        "scheduleStatus": schedule_status,
        "observedStatus": observed_status,
        "openingBlocked": gate_blocked,
        "openingGate": public_state.get("openingGate", {
            "status": public_state.get("openingGateStatus", "idle")
        }),
        "finalized": finalized,
        "gradeOutbox": outbox,
        "state": public_state,
    }


def french8_final_exam_scheduler_wait_seconds():
    """Sleep until the next boundary, capped so health remains observable."""

    try:
        with data_lock:
            state = final_exam_level_config("french8")["readBundle"]().get("state", {})
        if state.get("scheduleEnabled") is not True:
            return 15.0
        current = datetime.now(timezone.utc)
        candidates = [
            value for value in (
                final_exam_parse_utc(state.get("opensAt")),
                final_exam_parse_utc(state.get("closesAt")),
            )
            if value and value > current
        ]
        if not candidates:
            return 5.0
        return max(0.25, min(15.0, (min(candidates) - current).total_seconds()))
    except Exception:
        return 5.0


def french8_final_exam_scheduler_loop():
    owner = "progress-api-scheduler:" + str(os.getpid())
    repository = None
    lease_token = None
    FRENCH8_FINAL_EXAM_RUNTIME_STATUS.update({
        "schedulerEnabled": True,
        "schedulerStartedAt": now_iso(),
    })
    try:
        while not FRENCH8_FINAL_EXAM_SCHEDULER_STOP.is_set():
            try:
                repository = french8_final_exam_repository()
                if not lease_token:
                    lease_token = repository.acquire_scheduler_lease(owner, lease_seconds=45)
                    if not lease_token:
                        FRENCH8_FINAL_EXAM_RUNTIME_STATUS.update({
                            "schedulerLeaseOwner": "another_process",
                            "schedulerLastTickAt": now_iso(),
                        })
                        FRENCH8_FINAL_EXAM_SCHEDULER_WAKE.wait(5)
                        FRENCH8_FINAL_EXAM_SCHEDULER_WAKE.clear()
                        continue
                result = french8_final_exam_scheduler_tick()
                scheduler_state = repository.record_scheduler_tick(
                    owner,
                    lease_token,
                    success=True,
                    state={
                        "scheduleStatus": result.get("scheduleStatus"),
                        "observedStatus": result.get("observedStatus"),
                        "openingBlocked": result.get("openingBlocked") is True,
                        "openingGate": result.get("openingGate", {}),
                        "finalized": result.get("finalized", False),
                        "gradeOutbox": result.get("gradeOutbox", {}),
                    },
                    lease_seconds=45,
                )
                FRENCH8_FINAL_EXAM_RUNTIME_STATUS["schedulerLeaseOwner"] = scheduler_state.get("leaseOwner")
            except FinalExamConflictError:
                lease_token = None
                FRENCH8_FINAL_EXAM_RUNTIME_STATUS.update({
                    "schedulerLastTickAt": now_iso(),
                    "schedulerLastError": "scheduler_lease_lost",
                })
            except Exception as error:
                failures = int(FRENCH8_FINAL_EXAM_RUNTIME_STATUS.get("schedulerConsecutiveFailures", 0) or 0) + 1
                FRENCH8_FINAL_EXAM_RUNTIME_STATUS.update({
                    "schedulerLastTickAt": now_iso(),
                    "schedulerLastError": clean_text(error, 300) or error.__class__.__name__,
                    "schedulerConsecutiveFailures": failures,
                })
                if repository is not None and lease_token:
                    try:
                        repository.record_scheduler_tick(
                            owner,
                            lease_token,
                            success=False,
                            state={"component": "final_exam_scheduler"},
                            error=clean_text(error, 1000) or error.__class__.__name__,
                            lease_seconds=45,
                        )
                    except Exception:
                        lease_token = None
                if repository is not None:
                    try:
                        repository.record_alert(
                            "scheduler",
                            "critical" if failures >= 3 else "error",
                            message="Le planificateur autonome a échoué.",
                            context={
                                "consecutiveFailures": failures,
                                "error": clean_text(error, 500) or error.__class__.__name__,
                            },
                        )
                    except Exception:
                        pass
                print(json.dumps({
                    "level": "french8",
                    "component": "final_exam_scheduler",
                    "severity": "critical" if failures >= 3 else "warning",
                    "error": clean_text(error, 300) or error.__class__.__name__,
                    "at": now_iso(),
                }, ensure_ascii=False, sort_keys=True))
            wait_seconds = french8_final_exam_scheduler_wait_seconds()
            FRENCH8_FINAL_EXAM_SCHEDULER_WAKE.wait(wait_seconds)
            FRENCH8_FINAL_EXAM_SCHEDULER_WAKE.clear()
    finally:
        if repository is not None and lease_token:
            try:
                repository.release_scheduler_lease(owner, lease_token)
            except Exception:
                pass


def start_french8_final_exam_scheduler():
    global FRENCH8_FINAL_EXAM_SCHEDULER_THREAD
    if FRENCH8_FINAL_EXAM_SCHEDULER_THREAD and FRENCH8_FINAL_EXAM_SCHEDULER_THREAD.is_alive():
        return FRENCH8_FINAL_EXAM_SCHEDULER_THREAD
    FRENCH8_FINAL_EXAM_SCHEDULER_STOP.clear()
    FRENCH8_FINAL_EXAM_SCHEDULER_WAKE.clear()
    thread = threading.Thread(
        target=french8_final_exam_scheduler_loop,
        name="french8-final-exam-scheduler",
        daemon=False,
    )
    FRENCH8_FINAL_EXAM_SCHEDULER_THREAD = thread
    thread.start()
    return thread


def stop_french8_final_exam_scheduler(timeout=10):
    FRENCH8_FINAL_EXAM_SCHEDULER_STOP.set()
    FRENCH8_FINAL_EXAM_SCHEDULER_WAKE.set()
    thread = FRENCH8_FINAL_EXAM_SCHEDULER_THREAD
    if thread and thread.is_alive() and thread is not threading.current_thread():
        thread.join(max(0.1, float(timeout)))
    FRENCH8_FINAL_EXAM_RUNTIME_STATUS["schedulerEnabled"] = False


def french8_final_exam_realtime_snapshot(profile):
    config = final_exam_level_config("french8")
    grades_data = read_grades_data(config["gradesPath"])
    grades_changed = config["ensureGrades"](grades_data)
    role, student = final_exam_authorized(profile, grades_data)
    if role not in ("admin", "teacher") and not isinstance(student, dict):
        raise PermissionError("student_not_authorized")
    bundle = config["readBundle"]()
    store = config["readStore"]()
    store_changed, due_grades = final_exam_finalize_due_attempts(config, grades_data, bundle, store)
    grades_changed = grades_changed or due_grades
    if store_changed:
        config["writeStore"](store)
    if grades_changed:
        write_json_file(config["gradesPath"], grades_data, ".final-exam-grades-")
    student_id = clean_text(student.get("id"), 40) if isinstance(student, dict) else ""
    payload = {
        "schemaVersion": 1,
        "serverTime": now_iso(),
        "role": role,
        "state": final_exam_public_state(bundle.get("state", {}), role, student_id),
    }
    if role in ("admin", "teacher"):
        monitor = final_exam_monitor_payload(config, grades_data, bundle, store)
        payload["counts"] = monitor.get("counts", {})
        payload["integrity"] = monitor.get("integrity", {})
        payload["students"] = monitor.get("students", [])
        payload["sessions"] = payload["students"]
    else:
        attempt = final_exam_matching_attempt(store, student, bundle.get("exam", {}))
        submission = store.get("submissions", {}).get(student_id)
        payload["student"] = student_public_view(student)
        payload["attempt"] = {
            "status": clean_text(attempt.get("status"), 40) or "in_progress",
            "answeredCount": len(attempt.get("answers", {})) if isinstance(attempt, dict) and isinstance(attempt.get("answers"), dict) else 0,
            "revision": int(attempt.get("revision", 0) or 0) if isinstance(attempt, dict) else 0,
            "timing": final_exam_attempt_timing(bundle.get("state", {}), attempt, student_id) if isinstance(attempt, dict) and not isinstance(submission, dict) else None,
        } if isinstance(attempt, dict) else None
        payload["submitted"] = isinstance(submission, dict)
    return payload


def serve_french8_final_exam_sse(handler, profile, cycles=6, interval_seconds=4):
    """Serve a bounded authenticated SSE stream; clients reconnect automatically."""

    handler.send_response(200)
    handler.send_header("Content-Type", "text/event-stream; charset=utf-8")
    handler.send_header("Cache-Control", "no-store")
    handler.send_header("Connection", "close")
    handler.send_header("X-Accel-Buffering", "no")
    request_id = clean_text(getattr(handler, "request_id", ""), 120)
    if request_id:
        handler.send_header("X-Request-ID", request_id)
    handler.end_headers()
    FRENCH8_FINAL_EXAM_RUNTIME_STATUS["sseConnections"] = int(
        FRENCH8_FINAL_EXAM_RUNTIME_STATUS.get("sseConnections", 0) or 0
    ) + 1
    previous_fingerprint = ""
    try:
        for sequence in range(max(1, int(cycles))):
            if FRENCH8_FINAL_EXAM_SCHEDULER_STOP.is_set():
                break
            with data_lock:
                snapshot = french8_final_exam_realtime_snapshot(profile)
            canonical = json.dumps(snapshot, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
            fingerprint = hashlib.sha256(canonical.encode("utf-8")).hexdigest()
            if sequence == 0 or fingerprint != previous_fingerprint:
                event_id = str(int(time.time() * 1000)) + "-" + str(sequence)
                frame = (
                    "id: " + event_id + "\n"
                    "event: snapshot\n"
                    "retry: 3000\n"
                    "data: " + canonical + "\n\n"
                ).encode("utf-8")
                handler.wfile.write(frame)
                previous_fingerprint = fingerprint
            else:
                handler.wfile.write((": heartbeat " + now_iso() + "\n\n").encode("utf-8"))
            handler.wfile.flush()
            if sequence + 1 < max(1, int(cycles)):
                time.sleep(max(1, float(interval_seconds)))
    except (BrokenPipeError, ConnectionResetError, OSError):
        pass
    finally:
        handler.close_connection = True
        FRENCH8_FINAL_EXAM_RUNTIME_STATUS["sseConnections"] = max(
            0, int(FRENCH8_FINAL_EXAM_RUNTIME_STATUS.get("sseConnections", 1) or 1) - 1
        )


def french8_final_exam_audit_public(event):
    detail = event.get("detail", {}) if isinstance(event, dict) else {}
    if not isinstance(detail, dict):
        detail = {"value": clean_text(detail, 500)}
    event_type = clean_text(event.get("eventType"), 160) if isinstance(event, dict) else ""
    return {
        "id": event.get("id") if isinstance(event, dict) else None,
        "type": event_type,
        "event": event_type,
        "eventType": event_type,
        "occurredAt": event.get("occurredAt") if isinstance(event, dict) else None,
        "actor": event.get("actorEmail") if isinstance(event, dict) else "",
        "actorEmail": event.get("actorEmail") if isinstance(event, dict) else "",
        "studentId": event.get("studentId") if isinstance(event, dict) else "",
        "requestId": event.get("requestId") if isinstance(event, dict) else "",
        "source": event.get("source") if isinstance(event, dict) else "",
        "detail": detail,
        "message": json.dumps(detail, ensure_ascii=False, sort_keys=True) if detail else "",
    }


def french8_final_exam_alert_public(alert):
    if not isinstance(alert, dict):
        return {}
    code = clean_text(alert.get("alertKey"), 160) or "technical_alert"
    severity = clean_text(alert.get("severity"), 40).lower() or "warning"
    status = clean_text(alert.get("status"), 40).lower() or "open"
    return {
        "id": code,
        "alertId": code,
        "code": code,
        "severity": severity,
        "status": status,
        "message": clean_text(alert.get("message"), 1000),
        "context": alert.get("context") if isinstance(alert.get("context"), dict) else {},
        "firstSeenAt": alert.get("firstSeenAt"),
        "lastSeenAt": alert.get("lastSeenAt"),
        "occurrences": int(alert.get("occurrences", 1) or 1),
        "acknowledgedAt": alert.get("acknowledgedAt"),
        "acknowledgedBy": alert.get("acknowledgedBy"),
        "resolvedAt": alert.get("resolvedAt"),
        "blocking": status != "resolved" and severity in ("error", "critical"),
    }


def french8_final_exam_grade_sync_diagnostics(grades_data, store):
    students = {
        clean_text(item.get("id"), 80): item
        for item in grades_data.get("students", [])
        if isinstance(item, dict) and clean_text(item.get("id"), 80)
    }
    divergences = []
    missing_students = []
    for student_id, submission in store.get("submissions", {}).items():
        student_key = clean_text(student_id, 80)
        student = students.get(student_key)
        if not isinstance(student, dict):
            missing_students.append(student_key)
            continue
        expected = clean_grade(submission.get("grade")) if isinstance(submission, dict) else None
        actual = clean_grade(student.get("grades", {}).get("finalExam")) if isinstance(student.get("grades"), dict) else None
        if expected != actual:
            divergences.append({"studentId": student_key, "expected": expected, "actual": actual})
    return {
        "ok": not divergences and not missing_students,
        "submissionCount": len(store.get("submissions", {})),
        "divergenceCount": len(divergences),
        "missingStudentCount": len(missing_students),
        "divergences": divergences[:20],
        "missingStudents": missing_students[:20],
    }


def french8_final_exam_seed_grade_outbox(repository, store):
    seeded = 0
    for student_id, submission in store.get("submissions", {}).items():
        if not isinstance(submission, dict):
            continue
        student_key = clean_text(student_id, 80)
        grade = clean_grade(submission.get("grade"))
        attempt_id = clean_text(submission.get("attemptId"), 160)
        receipt = clean_text(submission.get("receiptCode"), 160)
        if not student_key or grade is None or not attempt_id:
            continue
        repository.enqueue_grade_sync(
            student_key,
            grade,
            attempt_id,
            evaluation_id="finalExam",
            idempotency_key="french8:" + (receipt or attempt_id),
            payload={
                "receiptCode": receipt,
                "examVersion": clean_text(submission.get("examVersion"), 80),
                "submittedAt": clean_text(submission.get("submittedAt"), 80),
            },
        )
        seeded += 1
    return seeded


def french8_final_exam_reconcile_grade_outbox(config, grades_data, store):
    repository_factory = config.get("repository") if isinstance(config, dict) else None
    if not callable(repository_factory):
        return {"claimed": 0, "completed": 0, "retried": 0, "gradesChanged": False}
    repository = repository_factory()
    french8_final_exam_seed_grade_outbox(repository, store)
    worker_id = "progress-api-grade:" + str(os.getpid())
    claimed = repository.claim_grade_outbox(worker_id, limit=100, lease_seconds=60)
    if not claimed:
        return {"claimed": 0, "completed": 0, "retried": 0, "gradesChanged": False}
    students = {
        clean_text(item.get("id"), 80): item
        for item in grades_data.get("students", [])
        if isinstance(item, dict) and clean_text(item.get("id"), 80)
    }
    ready = []
    retried = 0
    grades_changed = False
    for item in claimed:
        student = students.get(clean_text(item.get("studentId"), 80))
        if not isinstance(student, dict):
            repository.retry_grade_outbox(
                item["id"], worker_id, item["claimToken"], "student_not_found", retry_after_seconds=300
            )
            retried += 1
            continue
        grade = clean_grade(item.get("grade"))
        if grade is None:
            repository.retry_grade_outbox(
                item["id"], worker_id, item["claimToken"], "invalid_grade", retry_after_seconds=3600
            )
            retried += 1
            continue
        if student.setdefault("grades", {}).get("finalExam") != grade:
            student["grades"]["finalExam"] = grade
            grades_changed = True
        ready.append(item)
    if grades_changed:
        write_json_file(config["gradesPath"], grades_data, ".final-exam-grades-")
    for item in ready:
        repository.complete_grade_outbox(item["id"], worker_id, item["claimToken"])
    return {
        "claimed": len(claimed),
        "completed": len(ready),
        "retried": retried,
        "gradesChanged": grades_changed,
    }


def french8_final_exam_sync_operational_alerts(repository, checks):
    alert_checks = {
        "database": "Base de données transactionnelle indisponible ou non intègre.",
        "scheduler": "Le planificateur autonome requiert une intervention.",
        "audio": "Le fichier audio professionnel ou sa diffusion Range n'est pas prêt.",
        "gradebook": "Une divergence de notes attend sa conciliation.",
        "audit": "Le journal d'audit n'est pas disponible.",
    }
    for code, fallback_message in alert_checks.items():
        check = checks.get(code, {}) if isinstance(checks, dict) else {}
        status = clean_text(check.get("status"), 40).lower()
        existing = repository.get_alert(code)
        if status in ("warning", "degraded", "error", "blocked"):
            severity = "critical" if status == "blocked" else ("error" if status == "error" else "warning")
            message = clean_text(check.get("message"), 1000) or fallback_message
            context = check.get("context") if isinstance(check.get("context"), dict) else {}
            needs_record = (
                existing is None
                or existing.get("status") == "resolved"
                or existing.get("severity") != severity
                or existing.get("message") != message
                or existing.get("context") != context
            )
            if needs_record:
                repository.record_alert(code, severity, message=message, context=context)
        elif existing and existing.get("status") != "resolved":
            repository.resolve_alert(code, "system", resolution="health_check_recovered")


def french8_final_exam_health_payload(config=None, grades_data=None, bundle=None, store=None, record_alerts=True):
    config = config or final_exam_level_config("french8")
    repository_factory = config.get("repository") if isinstance(config, dict) else None
    repository = repository_factory() if callable(repository_factory) else french8_final_exam_repository()
    storage = repository.health(deep=False)
    grades_data = grades_data if isinstance(grades_data, dict) else read_grades_data(config["gradesPath"])
    if callable(config.get("ensureGrades")):
        config["ensureGrades"](grades_data)
    bundle = bundle if isinstance(bundle, dict) else config["readBundle"]()
    store = store if isinstance(store, dict) else config["readStore"]()
    integrity = final_exam_integrity(bundle.get("exam", {}), final_exam_audio_path(config))
    weighting_issue = final_exam_weighting_issue(grades_data)
    grade_sync = french8_final_exam_grade_sync_diagnostics(grades_data, store)
    scheduler = storage.get("scheduler") if isinstance(storage.get("scheduler"), dict) else {}
    scheduler_last_success = scheduler.get("lastSuccessAt") or FRENCH8_FINAL_EXAM_RUNTIME_STATUS.get("schedulerLastSuccessAt")
    scheduler_age = None
    parsed_success = final_exam_parse_utc(scheduler_last_success)
    if parsed_success:
        scheduler_age = max(0, int((datetime.now(timezone.utc) - parsed_success).total_seconds()))
    scheduler_enabled = FRENCH8_FINAL_EXAM_RUNTIME_STATUS.get("schedulerEnabled") is True
    scheduler_failures = max(
        int(scheduler.get("consecutiveFailures", 0) or 0),
        int(FRENCH8_FINAL_EXAM_RUNTIME_STATUS.get("schedulerConsecutiveFailures", 0) or 0),
    )
    scheduler_ok = scheduler_enabled and scheduler_failures == 0 and scheduler_age is not None and scheduler_age <= 45
    free_bytes = int(storage.get("freeBytes", 0) or 0)
    database_ok = storage.get("ok") is True and free_bytes >= 100 * 1024 * 1024
    pending_outbox = int(storage.get("pendingGradeOutbox", 0) or 0)
    gradebook_ok = grade_sync.get("ok") is True and pending_outbox == 0
    checks = {
        "api": {
            "status": "ok",
            "ok": True,
            "message": "API authentifiée disponible; identifiant de requête actif.",
        },
        "database": {
            "status": "ok" if database_ok else "blocked",
            "ok": database_ok,
            "message": (
                "SQLite WAL intègre et espace disque disponible."
                if database_ok
                else "SQLite, sa migration ou l'espace disque ne permet pas une ouverture sûre."
            ),
            "context": {
                "schemaVersion": storage.get("schemaVersion"),
                "freeBytes": free_bytes,
                "databaseBytes": storage.get("databaseBytes"),
            },
        },
        "scheduler": {
            "status": "ok" if scheduler_ok else ("error" if scheduler_failures else "degraded"),
            "ok": scheduler_ok,
            "message": (
                "Planificateur autonome actif; dernier passage il y a %s s." % scheduler_age
                if scheduler_ok
                else "Planificateur sans battement récent ou avec échec; l'ouverture manuelle reste contrôlée."
            ),
            "context": {
                "enabled": scheduler_enabled,
                "lastSuccessAt": scheduler_last_success,
                "ageSeconds": scheduler_age,
                "consecutiveFailures": scheduler_failures,
            },
        },
        "audio": {
            "status": "ok" if integrity.get("audioAvailable") else "blocked",
            "ok": integrity.get("audioAvailable") is True,
            "message": "Audio professionnel disponible avec requêtes Range." if integrity.get("audioAvailable") else "Audio professionnel absent.",
            "context": {"acceptRanges": True, "integrityIssues": integrity.get("issues", [])},
        },
        "sse": {
            "status": "ok",
            "ok": True,
            "message": "Canal temps réel actif; %s connexion(s)." % int(FRENCH8_FINAL_EXAM_RUNTIME_STATUS.get("sseConnections", 0) or 0),
        },
        "gradebook": {
            "status": "ok" if gradebook_ok and not weighting_issue else ("blocked" if weighting_issue else "degraded"),
            "ok": gradebook_ok and not weighting_issue,
            "message": (
                "Carnet et livraisons synchronisés."
                if gradebook_ok and not weighting_issue
                else "Conciliation en attente ou pondération invalide."
            ),
            "context": dict(grade_sync, pendingOutbox=pending_outbox, weightingIssue=weighting_issue),
        },
        "audit": {
            "status": "ok" if storage.get("auditEvents") is not None else "error",
            "ok": storage.get("auditEvents") is not None,
            "message": "%s événement(s) append-only disponibles." % int(storage.get("auditEvents", 0) or 0),
        },
    }
    if not integrity.get("ok") and integrity.get("audioAvailable"):
        checks["audio"]["status"] = "blocked"
        checks["audio"]["ok"] = False
        checks["audio"]["message"] = "L'intégrité du contenu d'examen doit être corrigée avant l'ouverture."
    if record_alerts:
        french8_final_exam_sync_operational_alerts(repository, checks)
    alerts = [french8_final_exam_alert_public(item) for item in repository.list_alerts(active_only=False, limit=100)]
    blocking_issues = [key for key, value in checks.items() if value.get("status") == "blocked"]
    degraded = [key for key, value in checks.items() if value.get("status") in ("warning", "degraded", "error")]
    status = "blocked" if blocking_issues else ("degraded" if degraded else "ok")
    state_opening_gate = (
        bundle.get("state", {}).get("openingGate")
        if isinstance(bundle.get("state", {}).get("openingGate"), dict)
        else {}
    )
    opening_gate_checked_candidates = [
        value
        for value in (
            state_opening_gate.get("checkedAt"),
            FRENCH8_FINAL_EXAM_RUNTIME_STATUS.get("scheduledOpeningGateCheckedAt"),
        )
        if final_exam_parse_utc(value) is not None
    ]
    opening_gate_checked_at = (
        final_exam_iso_utc(max(
            opening_gate_checked_candidates,
            key=lambda value: final_exam_parse_utc(value),
        ))
        if opening_gate_checked_candidates
        else None
    )
    payload = {
        "ok": not blocking_issues,
        "status": status,
        "readyToOpen": not blocking_issues,
        "schedulerReady": scheduler_ok,
        "serverTime": now_iso(),
        "checks": checks,
        "alerts": alerts,
        "blockingIssues": blocking_issues,
        "degradedChecks": degraded,
        "storage": storage,
        "openingGate": {
            "status": clean_text(
                state_opening_gate.get("status")
                or FRENCH8_FINAL_EXAM_RUNTIME_STATUS.get("scheduledOpeningGateStatus"),
                40,
            ) or "idle",
            "checkedAt": opening_gate_checked_at,
            "blockingIssues": list(
                state_opening_gate.get("blockingIssues", [])
                or FRENCH8_FINAL_EXAM_RUNTIME_STATUS.get("scheduledOpeningBlockingIssues", [])
            ),
            "lastError": clean_text(
                state_opening_gate.get("lastError")
                or FRENCH8_FINAL_EXAM_RUNTIME_STATUS.get("scheduledOpeningLastError"),
                300,
            ),
        },
    }
    FRENCH8_FINAL_EXAM_RUNTIME_STATUS["lastHealthAt"] = payload["serverTime"]
    FRENCH8_FINAL_EXAM_RUNTIME_STATUS["lastHealthStatus"] = status
    return payload


def ensure_final_exam_evaluation(grades_data):
    evaluations = grades_data.setdefault("evaluations", [])
    if any(isinstance(item, dict) and item.get("id") == "finalExam" for item in evaluations):
        return
    evaluations.insert(0, {
        "id": "finalExam",
        "title": "Examen final",
        "weight": 20,
        "type": "Examen",
        "date": "2026-06-05",
        "displayDate": "Vendredi 5 juin",
        "description": "Evaluation finale sur les themes principaux du cours."
    })



